/**
 * 사이트루미 예약 — 구매자 구글 캘린더에 저장 (데이터는 모두 구매자 계정)
 * ------------------------------------------------------------------------
 *  - 홈페이지 「예약」 섹션이 빈 시간을 물어보면(bookSlots) 앞으로 N일의 예약 가능한 시간을 한 번에 돌려줌
 *    영업시간(가게 정보) − 이미 잡힌 예약(「사이트루미 예약」 캘린더) − 지금부터 최소 준비 시간
 *  - 손님이 예약하면(book) 캘린더에 일정을 만들고, 문의함에도 남기고, 사장님께 메일
 *  - 예약 확인·변경·취소는 휴대폰 구글 캘린더 앱에서 (일정을 지우면 그 시간이 다시 열림)
 *  - 설정(시간 단위·며칠 앞까지·준비 시간·동시 예약 수·서비스 목록)은 편집기 「예약」 섹션에서 → 저장할 때 BOOK_CFG 로 보관
 */

var BOOK_CAL_NAME = '사이트루미 예약';
var BOOK_PER_MIN = 10;              // 1분에 받는 예약 수 (몰림 방지)
var BOOK_DAYS_IDX = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];

/** 저장할 때 예약 설정을 따로 보관 (손님 요청마다 사이트 전체를 읽지 않게) */
function bookSaveCfg_(site) {
  var sec = null;
  Object.keys(site.sections || {}).some(function (k) { var s = site.sections[k]; if (s && s.type === 'booking') { sec = s; return true; } return false; });
  if (!sec) { PROPS.deleteProperty('BOOK_CFG'); return; }
  var d = sec.data || {}, num = function (v, lo, hi, def) { v = Number(v); return isFinite(v) && v >= lo && v <= hi ? Math.round(v) : def; };
  var cfg = {
    slot: [15, 20, 30, 40, 60, 90, 120].indexOf(Number(d.slot)) >= 0 ? Number(d.slot) : 60,
    days: num(d.days, 1, 60, 14), ahead: num(d.ahead, 0, 72, 2), cap: num(d.cap, 1, 20, 1),
    services: (Array.isArray(d.services) ? d.services : String(d.services || '').split(/\n|,/)).map(function (x) { return String(x).trim().slice(0, 40); }).filter(String).slice(0, 20),
    hours: (site.biz || {}).hours || {}, name: (site.biz || {}).name || ''
  };
  PROPS.setProperty('BOOK_CFG', JSON.stringify(cfg));
  CacheService.getScriptCache().remove('BOOK_SLOTS');
}
function bookCfg_() { return safeJson_(PROPS.getProperty('BOOK_CFG') || 'null'); }

/** 예약 캘린더 (없으면 만듦) */
function bookCalendar_() {
  var id = PROPS.getProperty('BOOK_CAL_ID'), cal = id ? CalendarApp.getCalendarById(id) : null;
  if (!cal) {
    var found = CalendarApp.getCalendarsByName(BOOK_CAL_NAME);
    cal = found.length ? found[0] : CalendarApp.createCalendar(BOOK_CAL_NAME, { color: CalendarApp.Color.BLUE, timeZone: 'Asia/Seoul' });
    PROPS.setProperty('BOOK_CAL_ID', cal.getId());
  }
  return cal;
}

/** "10:00-20:00" → [600, 1200] (분) · 휴무·비어 있으면 null */
function bookRange_(s) {
  var m = String(s || '').match(/(\d{1,2}):(\d{2})\s*[-~]\s*(\d{1,2}):(\d{2})/);
  if (!m) return null;
  var a = Number(m[1]) * 60 + Number(m[2]), b = Number(m[3]) * 60 + Number(m[4]);
  if (b <= a) b += 24 * 60;            // 자정 넘김
  return [a, b];
}

/** 빈 시간 계산 (순수 함수 — 시험하기 쉽게): now(Date), events [{s,e}](ms) */
function bookCompute_(cfg, now, events) {
  var tz = 'Asia/Seoul', out = [], slotMs = cfg.slot * 60000, minStart = now.getTime() + cfg.ahead * 3600000;
  var ymd = function (d) { return Utilities.formatDate(d, tz, 'yyyy-MM-dd'); };
  var today = ymd(now);
  for (var i = 0; i < cfg.days; i++) {
    var dayStr = ymd(new Date(now.getTime() + i * 86400000));
    if (i > 0 && dayStr === today) continue;
    var base = new Date(dayStr + 'T00:00:00+09:00').getTime();
    var dow = new Date(base + 9 * 3600000).getUTCDay();
    var r = bookRange_(cfg.hours[BOOK_DAYS_IDX[dow]]), times = [];
    if (r) {
      for (var t = r[0]; t + cfg.slot <= r[1]; t += cfg.slot) {
        var s = base + t * 60000, e = s + slotMs;
        if (s < minStart) continue;
        var used = 0;
        for (var j = 0; j < events.length; j++) if (events[j].s < e && events[j].e > s) used++;
        if (used < cfg.cap) times.push(('0' + Math.floor(t / 60)).slice(-2) + ':' + ('0' + t % 60).slice(-2));   // 자정 넘긴 시간은 24:00·25:00 (다음날 새벽)
      }
    }
    out.push({ d: dayStr, w: dow, t: times });
  }
  return out;
}

/** 손님: 예약 가능한 시간 (1분 보관) */
function slBookSlots_() {
  var cfg = bookCfg_();
  if (!cfg) return { ok: false, code: 'OFF', error: '예약을 받지 않는 홈페이지입니다.' };
  var cache = CacheService.getScriptCache(), hit = cache.get('BOOK_SLOTS');
  if (hit) return JSON.parse(hit);
  var now = new Date(), end = new Date(now.getTime() + (cfg.days + 1) * 86400000);
  var events = bookCalendar_().getEvents(now, end)        // 종일 일정(휴무 등)도 그 날을 막음
    .map(function (ev) { return { s: ev.getStartTime().getTime(), e: ev.getEndTime().getTime() }; });
  var res = { ok: true, slot: cfg.slot, services: cfg.services, days: bookCompute_(cfg, now, events) };
  try { cache.put('BOOK_SLOTS', JSON.stringify(res), 60); } catch (e) {}
  return res;
}

/** 손님: 예약하기 */
function slBook_(req) {
  if (req.website) return { ok: true };
  var cfg = bookCfg_();
  if (!cfg) return { ok: false, code: 'OFF', error: '예약을 받지 않는 홈페이지입니다.' };
  var name = clip_(req.name, 40), phone = clip_(req.phone, 30), memo = clip_(req.msg, 500), svc = clip_(req.service, 40);
  var digits = phone.replace(/[^\d]/g, '');
  if (!name || digits.length < 8) return { ok: false, code: 'INPUT', error: '이름과 연락처를 확인해 주세요.' };
  if (!req.agree) return { ok: false, code: 'AGREE', error: '개인정보 수집·이용에 동의해 주세요.' };
  if (svc && cfg.services.length && cfg.services.indexOf(svc) < 0) svc = '';
  var dm = String(req.date || '').match(/^(\d{4})-(\d{2})-(\d{2})$/), tm = String(req.time || '').match(/^(\d{2}):(\d{2})$/);
  if (!dm || !tm) return { ok: false, code: 'INPUT', error: '예약 날짜와 시간을 골라 주세요.' };
  var cache = CacheService.getScriptCache(), n = Number(cache.get('BK_MIN') || 0);
  if (n >= BOOK_PER_MIN) return { ok: false, code: 'BUSY', error: '잠시 후 다시 시도해 주세요.' };
  cache.put('BK_MIN', String(n + 1), 60);

  if (Number(tm[1]) > 47 || Number(tm[2]) > 59) return { ok: false, code: 'INPUT', error: '예약 시간을 다시 골라 주세요.' };
  var start = new Date(new Date(req.date + 'T00:00:00+09:00').getTime() + (Number(tm[1]) * 60 + Number(tm[2])) * 60000), end = new Date(start.getTime() + cfg.slot * 60000);
  var lock = LockService.getScriptLock();
  if (!lock.tryLock(15000)) return { ok: false, code: 'BUSY', error: '잠시 후 다시 시도해 주세요.' };
  try {
    /* 고른 시간이 아직 비어 있는지 다시 확인 (동시에 두 사람이 같은 시간을 고른 경우) */
    var cal = bookCalendar_(), now = new Date();
    var events = cal.getEvents(new Date(start.getTime() - 86400000), new Date(end.getTime() + 86400000)).map(function (ev) { return { s: ev.getStartTime().getTime(), e: ev.getEndTime().getTime() }; });
    var day = bookCompute_(cfg, now, events).filter(function (x) { return x.d === req.date; })[0];
    if (!day || day.t.indexOf(req.time) < 0) return { ok: false, code: 'TAKEN', error: '방금 다른 분이 예약했거나 예약할 수 없는 시간이에요. 다른 시간을 골라 주세요.' };
    var tel = SL_RENDER.fmtTel(phone);
    var ev = cal.createEvent('[예약] ' + name + (svc ? ' · ' + svc : ''), start, end, {
      description: '이름: ' + name + '\n연락처: ' + tel + (svc ? '\n서비스: ' + svc : '') + (memo ? '\n요청: ' + memo : '') + '\n\n홈페이지 예약 (사이트루미)'
    });
    try { ev.addPopupReminder(60); } catch (e) {}
    cache.remove('BOOK_SLOTS');
    var when = Utilities.formatDate(start, 'Asia/Seoul', 'M월 d일(E) HH:mm').replace('Mon', '월').replace('Tue', '화').replace('Wed', '수').replace('Thu', '목').replace('Fri', '금').replace('Sat', '토').replace('Sun', '일');
    /* 문의함에도 남김 (대시보드에서 함께 보이게) */
    var lead = { t: Date.now(), name: name, phone: tel, msg: '[예약] ' + when + (svc ? ' · ' + svc : '') + (memo ? '\n' + memo : ''), page: '예약', st: 'new', kind: 'booking' };
    saveLead_('L_' + lead.t + '_' + Math.random().toString(36).slice(2, 6), lead);
    try { pruneLeads_(); } catch (e) {}
    try { addHit_({ b: 'booking' }); } catch (e) {}
    try { mailLead_(lead); } catch (e) {}
    return { ok: true, when: when };
  } finally { lock.releaseLock(); }
}

/**
 * 사이트루미 자체 판매 홈페이지 (sitelumi.blogspot.com)
 * STEP9_brandSite 를 한 번 실행하면 지금 사이트(샘플)를 사이트루미 판매 홈페이지로 바꿉니다.
 *   · 바꾸기 전 사이트 데이터는 블로거 임시글 페이지(sl-backup-날짜)로 보관
 *   · 예전 샘플 페이지(시술·가격, 갤러리, 디자이너)는 임시글로 돌아가고 주소는 남음
 *   · 그 뒤 문구·가격·버튼은 편집기에서 고치면 됩니다 (이 함수를 다시 돌리면 편집한 내용이 덮어써짐)
 */

function slBrandSite_() {
  var site = slBuildSite({
    industry: 'consulting',
    name: '사이트루미', nameEn: 'SITELUMI',
    owner: '박은주', email: 'hoonk9@naver.com',
    address: '인천광역시 연수구',
    skin: 'card', hero: 'sign',
    contacts: [{ t: 'contact' }, { t: 'kakao' }], mainAction: 'contact'
  });
  site.industryName = '홈페이지·모바일 명함 제작';
  site.schemaType = 'ProfessionalService';
  site.biz.company = '디씨젼';
  site.biz.smsText = '';
  site.buttons = [
    { t: 'contact', v: '', label: '무료 상담 신청', main: true },
    { t: 'link', v: '/p/pricing.html', label: '가격 보기' },
    { t: 'kakao', v: '', label: '카카오톡 상담' }         // 카카오톡 채널 주소를 편집기에서 넣으면 보임
  ];

  var D = function (type, data, opt) { return { type: type, ver: SL_RENDER.MODS[type].ver, data: data, opt: opt || {} }; };
  var keep = { card: site.sections.card, terms: site.sections.terms, privacy: site.sections.privacy };
  keep.card.data.person = '최훈구';
  keep.card.data.role = '디씨젼 솔루션 매니저';

  site.sections = {
    hero: D('hero', {
      eyebrow: '사이트루미 · 업종별 홈페이지 + 모바일 명함',
      title: '홈페이지와 모바일 명함을 한 번에',
      lead: '월 이용료 없이 한 번 결제로 끝.\n업종에 맞게 채워진 홈페이지를 사장님이 휴대폰으로 직접 고칩니다.',
      image: ''
    }),
    trust: D('trust', { items: [
      { value: '71개', label: '업종별 기본 구성' },
      { value: '20종', label: '디자인 스타일' },
      { value: '0원', label: '월 이용료' },
      { value: '199,000원', label: '1회 결제부터 (VAT 별도)' }
    ]}),
    about: D('about', {
      title: '왜 사이트루미인가요',
      body: '동네 가게에 필요한 건 화려한 기능보다, 손님이 찾았을 때 바로 믿고 연락할 수 있는 한 장의 얼굴입니다.\n\n사이트루미는 업종을 고르면 그 업종에 맞는 페이지와 문구, 연락 버튼이 처음부터 채워진 홈페이지를 만들어 드립니다. 같은 정보로 모바일 명함도 함께 만들어지고, 사장님은 휴대폰 편집기에서 가격과 영업시간, 사진 설명을 직접 고치면 됩니다.',
      image: '',
      points: [
        { title: '월 이용료 0원', text: '매달 내는 구독료가 없습니다. 한 번 결제하면 계속 씁니다. 개인 도메인을 쓸 때만 도메인 비용이 따로 듭니다.' },
        { title: '홈페이지 + 모바일 명함', text: '같은 정보로 둘 다 만들어집니다. 손님에게 홈페이지를 보낼지, 명함을 보낼지 골라서 보내면 됩니다.' },
        { title: '사장님 계정, 사장님 소유', text: '사장님 구글 계정의 블로그에 설치됩니다. 홈페이지와 문의 기록이 모두 사장님 것입니다.' },
        { title: '검색엔진이 바로 읽는 구조', text: '페이지마다 글이 그대로 들어간 HTML로 발행하고, 검색 제외가 필요한 페이지는 로봇 태그를 자동으로 붙입니다.' }
      ]
    }),
    features: D('services', {
      title: '주요 기능',
      priceMode: 'from',
      moreText: '기능 전체 보기',
      items: [
        { name: '업종 맞춤 자동 구성', desc: '71개 업종에 맞는 페이지·문구·연락 버튼을 처음부터 채워 드립니다. 빈 화면에서 시작하지 않습니다.', price: '', image: '' },
        { name: '모바일 명함', desc: '연락처 저장, 카카오톡·문자로 보내기까지. 사진형·기업형·개성형 등 9가지 스타일 중 고를 수 있습니다.', price: '', image: '' },
        { name: '휴대폰 편집기', desc: '문구, 가격, 영업시간, 버튼, 섹션 순서를 휴대폰에서 고치고 저장하면 홈페이지에 바로 반영됩니다.', price: '', image: '' },
        { name: '상담 신청 알림', desc: '손님이 상담 신청을 남기면 사장님 이메일로 바로 알려 드리고, 편집기 문의함에 모아 둡니다. 스팸 차단 포함.', price: '', image: '' },
        { name: '방문 통계', desc: '블로거 기준 날짜별 방문 수와 전화·길찾기·카톡 버튼을 누른 횟수, 어디서 들어왔는지를 한 화면에서 봅니다.', price: '', image: '' },
        { name: '검색 최적화 기본 탑재', desc: '페이지별 제목·설명, 자주 묻는 질문 구조화 데이터, 로봇 태그를 자동으로 넣습니다. 따로 설정할 것이 없습니다.', price: '', image: '' },
        { name: '이용약관·개인정보처리방침', desc: '사업자 정보만 넣으면 표준 문안이 자동으로 완성되고 바닥글에 연결됩니다.', price: '', image: '' },
        { name: '가벼운 화면', desc: '꼭 필요한 코드만 쓰고 첫 화면을 먼저 그립니다. 휴대폰에서도 빠르게 열립니다.', price: '', image: '' }
      ]
    }),
    hybrid: D('text', {
      title: '홈페이지로 보낼까, 명함으로 보낼까',
      body: '처음 연락한 손님에게는 가게를 한눈에 보여 주는 홈페이지를, 이미 아는 손님에게는 저장하기 쉬운 모바일 명함을 보내세요.\n\n둘은 같은 정보를 씁니다. 홈페이지에서 전화번호나 영업시간을 고치면 명함에도 그대로 반영됩니다. 색과 분위기도 홈페이지와 맞춰집니다.',
      btnText: '모바일 명함 예시 보기', btnUrl: '/p/card.html'
    }),
    families: D('services', {
      title: '지원 업종',
      lead: '12개 분야, 71개 업종의 기본 페이지와 문구가 준비되어 있습니다. 목록에 없는 업종은 가장 가까운 업종으로 시작해 맞춰 드립니다.',
      priceMode: 'from',
      items: [
        { name: '뷰티', desc: '미용실 · 네일숍 · 피부관리실 · 속눈썹·반영구 · 왁싱숍 · 마사지·스파 · 바버숍', price: '', image: '' },
        { name: '음식·카페', desc: '식당 · 카페 · 베이커리 · 주점 · 배달 전문점 · 반찬·도시락', price: '', image: '' },
        { name: '교육', desc: '학원 · 공부방 · 영어학원 · 음악학원 · 미술학원 · 태권도장 · 코딩학원 · 과외', price: '', image: '' },
        { name: '의료·약국', desc: '의원 · 치과 · 한의원 · 약국 · 동물병원 · 물리치료·재활', price: '', image: '' },
        { name: '시공·설비', desc: '인테리어 · 도배·장판 · 타일·욕실 · 설비·누수 · 전기공사 · 샷시·창호 · 페인트·도장', price: '', image: '' },
