/** STEP9 사이트루미 판매 홈페이지로 바꾸기 (한 번만) */
function STEP9_brandSite() {
  var cur = slLoad_();
  if (cur) {
    /* 지금 데이터를 임시글 페이지로 보관 (공개되지 않음) */
    var stamp = Utilities.formatDate(new Date(), 'Asia/Seoul', 'yyyyMMdd-HHmm');
    var bak = slStoreWrap_('backup', 'backup:' + (cur.rev || 0) + ':' + Utilities.base64Encode(JSON.stringify(cur), Utilities.Charset.UTF_8));
    var bp = api_('post', '/pages/', { title: 'sl-backup-' + stamp, content: bak }, { isDraft: 'true' });
    ok_(!!(bp && bp.id), '지금 사이트 데이터 보관 (임시글 페이지 sl-backup-' + stamp + ')');
  }
  var site = slBrandSite_();
  var res = slSave_(site, cur ? cur.rev : null);
  ok_(res.ok, '사이트루미 판매 홈페이지로 저장·발행', res.ok ? 'rev ' + res.rev : (res.error || ''));
  if (!res.ok) return done_('STEP9');
  Object.keys(res.pages || {}).forEach(function (k) { if (res.pages[k]) log_('   · ' + k + ' → ' + res.pages[k]); });
  log_('👉 예전 샘플 페이지(시술·가격 · 스타일 갤러리 · 디자이너)는 임시글로 돌아갔습니다. 블로거 › 페이지에서 지워도 됩니다.');
  log_('👉 편집기 › 기본 정보에서 사업자등록번호·통신판매업 신고번호를 넣고, 버튼에 카카오톡 채널 주소를 넣어 주세요.');
  done_('STEP9');
}

/**
 * 사이트루미 GAS 코어
 * ------------------------------------------------------------------------
 * 구매자 구글 계정에 설치되는 서버입니다. 키·비밀번호는 모두 '스크립트 속성'에만 저장됩니다.
 *
 * ▶ 설치는 Setup.gs 의 「설치하기」 하나만 실행하면 됩니다 (나머지는 웹앱 설치 화면이 안내).
 *
 * 아래 STEP 함수들은 문제가 생겼을 때 점검용입니다 (평소에는 실행할 필요 없음).
 *   STEP3_webapp      웹앱 응답 확인
 *   STEP4_loginTest   실제 웹앱으로 로그인 · 토큰 · 틀린 비번 거부 확인 (스크립트 속성 TEST_PW 필요)
 *   STEP5_mailTest    아이디·비밀번호 재발급 메일 발송 확인
 *   STEP7_pageCheck   페이지 주소 · 검색용 HTML · 로봇 태그 확인
 *   STEP8_dailyStats  블로거 기준 날짜별 방문 기록 (밤 12시) 확인·재설치
 *   STATUS            현재 설정 상태 한눈에 보기
 */

/* 고칠 것 없음 — 블로그 주소와 웹앱 주소는 설치 화면에서 자동으로 정해져 스크립트 속성(BLOG_URL · WEBAPP_URL)에 저장됩니다.
   (개발·시험용으로만 아래 값을 채워 쓸 수 있음. 판매용 파일은 반드시 비워 둘 것) */
var CONFIG = {
  BLOG_URL: '',
  WEBAPP_URL: ''
};

var CORE_VER = '4.1.7';
var TOKEN_HOURS = 24 * 7;          // 로그인 유지 7일
var LOGIN_MAX_FAIL = 5;            // 5번 틀리면
var LOGIN_LOCK_MIN = 15;           // 15분 잠금
var RESET_MIN = 15;                // 재발급 인증 번호 유효 15분
var RESET_MAX_TRY = 5;             // 인증 번호 5번까지 입력 가능

var PROPS = PropertiesService.getScriptProperties();

/* ═════════════════════════════ 설치 단계 ═════════════════════════════ */

/** STEP1 블로그 연결 + 설정 가젯 읽기 */
function STEP1_connect() {
  var id = null, err = '';
  try { id = blogId_(true); } catch (e) { err = e.message; }
  ok_(!!id, 'Blogger API 연결 · 블로그 찾기', id ? 'blogId=' + id : err);
  if (!id) {
    if (/403|has not been used|disabled|SERVICE_DISABLED|accessNotConfigured/i.test(err)) {
      log_('👉 Blogger API 가 꺼져 있거나 GCP 프로젝트가 연결되지 않았습니다.');
      log_('   가이드 STEP 0-B "GCP 프로젝트 연결" 순서대로 Blogger API 를 켜고 프로젝트 번호를 연결한 뒤 다시 실행하세요.');
    }
    return done_('STEP1');
  }
  var blog = api_('get', '', null, { fields: 'name,url,posts/totalItems,pages/totalItems' });
  log_('블로그: ' + blog.name + ' · ' + blog.url + ' · 글 ' + (blog.posts ? blog.posts.totalItems : 0) + '개 · 페이지 ' + (blog.pages ? blog.pages.totalItems : 0) + '개');

  var g = readGadgets_(true);
  ok_(!!g.site, '사이트 설정 가젯 (hp-site-config)', g.site ? JSON.stringify(g.site).slice(0, 160) : '홈 화면에서 찾지 못함 — 테마 적용·가젯 저장 확인');
  ok_(!!g.ai, 'AI 설정 가젯 (hp-ai-config)', g.ai ? 'provider=' + g.ai.provider + ', model=' + (g.ai.model || '(비어 있음)') : '찾지 못함');
  ok_(!!g.prompt, 'AI 지시문 가젯 (hp-ai-prompt)', g.prompt ? g.prompt.length + '자 · ' + g.prompt.split('\n')[0].slice(0, 40) : '찾지 못함');
  ok_(!!(g.labels && g.labels.labels), '라벨 사전 가젯 (hp-labels)', g.labels && g.labels.labels ? g.labels.labels.join(', ') : '찾지 못함');
  if (g.ai) ok_(!/key|sk-|AIza/i.test(JSON.stringify(g.ai)), 'AI 설정 가젯에 키 값이 없음 (안전)', '키는 스크립트 속성 AI_KEY 에만 넣기');
  PROPS.setProperty('BLOG_ID', id);
  done_('STEP1');
}

/**
 * STEP2 관리자 계정 등록
 * 먼저 [프로젝트 설정 ⚙ › 스크립트 속성]에 아래 3개를 추가한 뒤 실행:
 *   ADMIN_ID     로그인 아이디 (영문 소문자·숫자·_ 4~20자)
 *   ADMIN_PW     비밀번호 (8자 이상) — 실행하면 해시로 바뀌고 이 속성은 자동 삭제
 *   ADMIN_EMAIL  재발급 메일 받을 주소 (비우면 이 구글 계정 메일)
 */
function STEP2_setAdmin() {
  var id = String(PROPS.getProperty('ADMIN_ID') || '').trim().toLowerCase();
  var pw = PROPS.getProperty('ADMIN_PW');
  var email = String(PROPS.getProperty('ADMIN_EMAIL') || '').trim() || Session.getEffectiveUser().getEmail();
  if (!pw && PROPS.getProperty('ADMIN_HASH')) {
    log_('ℹ️ 이미 등록된 관리자: ' + id + ' · ' + maskEmail_(email) + ' — 비밀번호를 바꾸려면 ADMIN_PW 를 다시 넣고 실행');
    return;
  }
  ok_(/^[a-z0-9_]{4,20}$/.test(id), '아이디 형식 (영문 소문자·숫자·_ 4~20자)', id || '스크립트 속성 ADMIN_ID 없음');
  ok_(!!pw && String(pw).length >= 8, '비밀번호 8자 이상', pw ? String(pw).length + '자' : '스크립트 속성 ADMIN_PW 없음');
  ok_(/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email), '재발급 메일 주소', maskEmail_(email));
  if (RESULTS_.some(function (x) { return !x; })) return done_('STEP2');

  var t0 = Date.now();
  setPassword_(pw);
  PROPS.setProperties({ ADMIN_ID: id, ADMIN_EMAIL: email });
  PROPS.deleteProperty('ADMIN_PW');
  if (!PROPS.getProperty('TOKEN_SECRET')) PROPS.setProperty('TOKEN_SECRET', newSecret_());
  ok_(true, '비밀번호를 해시로 저장 (' + (Date.now() - t0) + 'ms)', '원문 ADMIN_PW 속성은 삭제됨');
  ok_(checkPassword_(pw) && !checkPassword_(pw + 'x'), '저장한 해시로 비밀번호 확인');
  done_('STEP2');
}

/** STEP3 웹앱 배포 확인 (가젯에 주소를 넣을 필요 없음 — 페이지마다 GAS 가 주소를 넣어 발행) */
function STEP3_webapp() {
  var url = webAppUrl_();
  if (!url) {
    log_('👉 웹앱을 먼저 배포하세요: [배포 › 새 배포 › 유형: 웹 앱] 실행: 나 / 액세스: 모든 사용자 → 배포');
    log_('   나온 웹앱 주소(…/exec)를 한 번 열면 자동으로 기억합니다 → 다시 실행');
    return;
  }
  ok_(WEBAPP_RE_.test(url), '웹앱 URL 형식 (…/exec)', url);
  var res = UrlFetchApp.fetch(url + '?a=ping', { muteHttpExceptions: true, followRedirects: true });
  var d = safeJson_(res.getContentText());
  ok_(d && d.ok && d.app === 'sitelumi', '웹앱 응답 (로그인 없이 접근 가능)', d ? 'core ' + d.ver : 'HTTP ' + res.getResponseCode() + ' — 액세스 "모든 사용자"로 배포했는지 확인');
  done_('STEP3');
}

/**
 * STEP4 로그인 확인 — 실제 웹앱에 요청을 보내 확인합니다.
 * [스크립트 속성]에 TEST_PW = (STEP2 에서 정한 비밀번호) 를 잠깐 넣고 실행 → 끝나면 자동 삭제
 */
function STEP4_loginTest() {
  var url = webAppUrl_(), pw = PROPS.getProperty('TEST_PW'), id = PROPS.getProperty('ADMIN_ID');
  if (!url) return log_('❌ 먼저 STEP3 를 통과하세요');
  if (!pw) return log_('👉 스크립트 속성에 TEST_PW = 관리자 비밀번호 를 넣고 다시 실행 (끝나면 자동 삭제)');
  try {
    var bad = callWeb_(url, { a: 'login', id: id, pw: pw + '#wrong' });
    ok_(bad && bad.ok === false && bad.code === 'LOGIN', '틀린 비밀번호는 거부', bad && bad.error);
    var t0 = Date.now();
    var r = callWeb_(url, { a: 'login', id: id, pw: pw });
    ok_(r && r.ok && r.token, '올바른 비밀번호로 로그인 · 토큰 발급', r && r.ok ? (Date.now() - t0) + 'ms' : JSON.stringify(r));
    if (r && r.token) {
      var w = callWeb_(url, { a: 'whoami', token: r.token });
      ok_(w && w.ok && w.id === id, '토큰으로 관리자 확인 (whoami)', w && w.id);
      var f = callWeb_(url, { a: 'whoami', token: r.token.slice(0, -2) + 'xx' });
      ok_(f && f.ok === false && f.code === 'AUTH', '위조 토큰 거부');
    }
    var cfg = callWeb_(url, { a: 'config' });
    ok_(cfg && cfg.ok && cfg.site, '공개 설정 읽기 (config) — 키·지시문은 내보내지 않음', cfg && cfg.site ? Object.keys(cfg).join(',') : '');
    ok_(cfg && !('prompt' in cfg) && !('key' in cfg), 'AI 지시문·키는 공개 응답에 없음');
  } finally {
    PROPS.deleteProperty('TEST_PW');
    log_('TEST_PW 속성 삭제함');
  }
  done_('STEP4');
}

