/** STEP7 페이지 주소 고정 · 검색용 HTML 확인 */
function STEP7_pageCheck() {
  var site = slLoad_();
  if (!site) return log_('❌ 먼저 STEP6 를 실행하세요');
  /* 블로그에 지금 걸린 테마가 v2.0 이상(로봇 태그 자동)인지 — 첫 화면 HTML 로 확인 */
  var home = fetchText_(blogUrl_().replace(/\/?$/, '/') + '?t=' + Date.now());
  var tv = /__slEarly/.test(home) ? 'v2.1 이상' : /field-sizing/.test(home) ? 'v2.0' : '';
  ok_(!!tv, '블로그에 적용된 테마 — 사이트루미 ' + (tv || '예전 버전'), tv ? '' : '테마 › HTML 편집에 sitelumi-theme.xml 전체를 붙여넣고 저장했는지 확인하세요');
  site.pages.forEach(function (p) {
    if (p.hidden || p.id === 'home') return;
    var pid = PROPS.getProperty('PG_' + p.id);
    var info = api_('get', '/pages/' + pid, null, { fields: 'url,title,status' });
    /* 블로거 주소는 처음 만들 때 정해지고 바뀌지 않음 → 예전 이름(designers 등)으로 만들어졌어도 영문 주소면 정상 */
    var m = String(info.url || '').match(/\/p\/([a-z0-9-]+)\.html$/), want = p.slug || p.id;
    ok_(!!m && info.title === p.title, p.title + ' — 영문 주소 + 한글 제목', info.url + ' · ' + info.title + (info.status ? ' · ' + info.status : ''));
    if (m && m[1] !== want) log_('   · 주소는 처음 만들 때 이름(' + m[1] + ') 그대로 씁니다. 바꾸지 않아도 됩니다 (바꾸면 기존 링크가 끊김).');
    var html = fetchText_(info.url + '?t=' + Date.now());
    ok_(/<section class="sl-sec/.test(html), '   검색용 HTML(섹션)이 공개 화면에 그대로 있음');
    var robots = (html.match(/<meta[^>]+name=["']robots["'][^>]*>/gi) || []);
    if (/^(card|terms|privacy)$/.test(p.id)) {
      /* 명함·약관·개인정보처리방침은 검색 결과에 안 나오게 (링크는 따라감) */
      ok_(robots.length === 1 && /noindex/.test(robots[0]) && !/nofollow/.test(robots[0]), '   로봇 태그 1개 · 검색 제외(noindex, follow)', robots.length + '개 ' + robots.join(' ').slice(0, 120));
      if (robots.length === 1 && !/noindex/.test(robots[0])) log_('   · 테마 v2.2 를 아직 적용하지 않았으면 적용 후 다시 실행하세요.');
    } else {
      ok_(robots.length === 1 && /index, follow/.test(robots[0]) && !/noindex/.test(robots[0]), '   로봇 태그 1개 · 검색 허용', robots.length + '개 ' + robots.join(' ').slice(0, 120));
    }
    if (p.sections.indexOf('faq') >= 0 && SL_RENDER.paid({ plan: slPlan_() })) ok_(/FAQPage/.test(html), '   FAQ 구조화 데이터가 지워지지 않고 남음', /FAQPage/.test(html) ? '' : '블로거가 본문 script 를 지움 → 테마 쪽 생성으로 대체 필요');
  });
  /* 데이터 저장용 페이지는 검색 제외 */
  ['DATA_PAGE', 'PG_home'].forEach(function (k) {
    var id = PROPS.getProperty(k); if (!id) return;
    var u = api_('get', '/pages/' + id, null, { fields: 'url' }).url;
    var h = fetchText_(u + '?t=' + Date.now());
    var r = (h.match(/<meta[^>]+name=["']robots["'][^>]*>/gi) || []);
    ok_(r.length === 1 && /noindex/.test(r[0]), (k === 'DATA_PAGE' ? 'sl-data' : 'sl-home') + ' 저장용 페이지 — 검색 제외(noindex)', r.join(' ').slice(0, 120));
  });
  done_('STEP7');
}

