/* ═════════════════════════════ 웹앱 API ═════════════════════════════ */

function doGet(e) {
  var a = e && e.parameter && e.parameter.a;
  if (a === 'ping') return json_({ ok: true, app: 'sitelumi', ver: CORE_VER });
  /* 그 밖에는 편집기 화면 (웹앱 주소를 열면 바로 관리자 화면) */
  var t = HtmlService.createTemplateFromFile('Editor');
  t.blogUrl = blogUrl_();
  rememberWebApp_();                                               // 이 웹앱 주소를 기억 (설치 화면·홈페이지 연결에 씀)
  t.tab = String((e && e.parameter && e.parameter.tab) || '');   // 홈페이지 관리 버튼에서 바로 열 탭 (dash · home · card · send …)
  t.setup = String((e && e.parameter && e.parameter.setup) || '').replace(/\D/g, '').slice(0, 6);   // 「설치하기」 로그의 설치 마무리 주소 (?setup=코드)
  t.demo = e && e.parameter && e.parameter.demo ? '1' : '';       // ?demo=1 : 누구나 써 보는 체험 편집기 (로그인·저장 없음)
  return t.evaluate()
    .setTitle(t.demo ? '사이트루미 · 내 사이트 만들어 보기' : '사이트루미 편집기 · ' + blogName_())
    .addMetaTag('viewport', 'width=device-width, initial-scale=1, viewport-fit=cover')
    .setXFrameOptionsMode(HtmlService.XFrameOptionsMode.DEFAULT);
}

/** Editor.html 안에서 다른 html 파일을 끼워 넣음 */
function include_(name) { return HtmlService.createHtmlOutputFromFile(name).getContent(); }
/** 편집기 미리보기·세팅에서 쓰는 공용 렌더러 원본 */
function renderSource_() { return '(' + SL_RENDER_FACTORY_.toString() + ')()'; }

/** 편집기 → 서버 (google.script.run.api) — 웹앱 POST 와 같은 경로 */
function api(req) {
  try { return route_(req || {}); }
  catch (err) { return { ok: false, code: 'ERR', error: String(err && err.message || err) }; }
}

/** 홈페이지 → GAS 요청 (Content-Type: text/plain 으로 JSON 문자열 전송) */
function doPost(e) {
  var req = safeJson_(e && e.postData && e.postData.contents) || {};
  var out;
  try { out = route_(req); }
  catch (err) { out = { ok: false, code: 'ERR', error: String(err && err.message || err) }; }
  return json_(out);
}

function route_(req) {
  switch (req.a) {
    case 'ping':         return { ok: true, app: 'sitelumi', ver: CORE_VER };
    case 'config':       return publicConfig_();
    case 'planCert':     return planApply_(req.cert);                              // 판매자 GAS 가 보내는 등급 증명 (서명으로 확인)
    case 'customCert':   return customApply_(req.cert);                            // 판매자 GAS 가 보내는 맞춤 코드 (서명으로 확인)
    case 'customAction': return withAuth_(req, function () { return customAction_(String(req.act || '')); });   // 편집기: 맞춤 코드 공개·되돌리기·끄기
    case 'planInfo':     return withAuth_(req, function () { return planInfo_(); });
    case 'planOrder':    return withAuth_(req, function () { return planOrder_(req); });
    case 'planPaste':    return withAuth_(req, function () { return planApply_(req.cert); });
    case 'sceneTaken':   return withAuth_(req, function () { var st = slLoad_(); return st ? sceneTaken_(st) : { ok: true, taken: [] }; });   // 편집기 씬 고르기: 이 지역에서 이미 쓰는 씬
    case 'login':        return login_(req);
    case 'whoami':       return withAuth_(req, function (u) { return { ok: true, id: u.u, exp: u.exp }; });
    case 'changePw':     return withAuth_(req, function () { return changePw_(req); });
    case 'resetRequest': return resetRequest_(req);
    case 'resetConfirm': return resetConfirm_(req);
    case 'load':         return withAuth_(req, function () { var st = slLoad_(); if (st) st.plan = slPlan_(); return { ok: true, site: st }; });
    case 'save':         return withAuth_(req, function () { return slSave_(req.site, req.baseRev); });
    case 'lead':         return slLead_(req);                // 손님 상담 신청 (로그인 없음)
    case 'hit':          return slHit_(req);                 // 손님 방문·버튼 기록 (로그인 없음)
    case 'bookSlots':    return slBookSlots_();              // 손님 예약 가능한 시간 (로그인 없음)
    case 'book':         return slBook_(req);                // 손님 예약 (로그인 없음)
    case 'leads':        return withAuth_(req, function () { return slLeads_(); });
    case 'leadSet':      return withAuth_(req, function () { return slLeadSet_(req); });
    case 'stats':        return withAuth_(req, function () { return slStats_(); });
    case 'boot':         return boot_();
    case 'demoDraft':    return demoDraft_(req);                                   // 체험 편집기: 답으로 사이트 미리 만들기 (저장 안 함)
    case 'setupInfo':    return setupInfo_(req);             // 설치 화면 (설치 코드로만)
    case 'setupCheck':   return setupCheck_(req);
    case 'setup':        return setup_(req);
    case 'checks':       return withAuth_(req, function () { return { ok: true, checks: siteChecks_(blogUrl_()) }; });
    case 'settings':     return withAuth_(req, function () { return settings_(); });
    case 'imgPut':       return withAuth_(req, function () { return slImgPut_(req); });
    case 'imgGet':       return withAuth_(req, function () { return slImgGet_(req); });
    case 'account':      return withAuth_(req, function () { return account_(req); });
    case 'repair':       return withAuth_(req, function () { installSnapTrigger_(); try { installUpdateTrigger_(); } catch (e) {} rememberWebApp_(); return settings_(); });
    case 'updateInfo':   return withAuth_(req, function () { return updateInfo_(!!req.fresh); });
    case 'updateNow':    return withAuth_(req, function () { if (req.optIn) PROPS.setProperty('UPDATE_MAJOR_OK', '1'); return updateApply_({ optIn: !!req.optIn }); });
    case 'updateRollback': return withAuth_(req, function () { return updateRollback_(); });
    case 'themeCss':     return { ok: true, css: themeCss_(!!req.fresh) };
    case 'shell':        return shell_(String(req.url || ''), !!req.fresh);           // 편집기 미리보기: 실제 블로그 화면 틀(테마·머리글·바닥글·스크립트)
    case 'draft':        return withAuth_(req, function () { return { ok: true, site: slEnsureCore(slBuildSite(req.answers || {})) }; });
    case 'build':        return withAuth_(req, function () {      // 처음 세팅 질문 답 → 사이트 생성·저장
                           var cur = slLoad_();
                           return slSave_(slBuildSite(req.answers), cur ? cur.rev : 0);
                         });
    default:             return { ok: false, code: 'ACTION', error: '서버 파일(Code.gs)이 예전 버전이라 이 기능을 모릅니다. 새로 받은 GAS 파일을 모두 바꾼 뒤 [배포 › 배포 관리 › 새 버전]으로 다시 배포해 주세요.' };
  }
}

/** 편집기 첫 화면에 필요한 공개 정보 (업종 목록 · 강점 · 블로그 주소) */
