/** 미리보기용 테마 CSS: 블로그 홈 화면의 <style> 과 글꼴 링크를 그대로 가져옴 (6시간 보관, 90KB 씩 나눠 저장) */
function themeCss_(fresh) {
  var cache = CacheService.getScriptCache();
  if (!fresh) {
    var n = Number(cache.get('CSS_N') || 0);
    if (n) {
      var parts = cache.getAll(Array.apply(null, Array(n)).map(function (x, i) { return 'CSS_' + i; }));
      var all = ''; for (var i = 0; i < n; i++) { if (parts['CSS_' + i] == null) { all = null; break; } all += parts['CSS_' + i]; }
      if (all) return all;
    }
  }
  var html = fetchText_(blogUrl_() + '?sl-css=' + Date.now());
  var out = (html.match(/<link[^>]+rel=['"]stylesheet['"][^>]*>/gi) || []).filter(function (l) { return /pretendard|pstatic|fonts|sitelumi(\.min)?\.css/i.test(l); }).join('\n');   // 얇은 테마: jsDelivr 디자인 파일도
  out += (html.match(/<style[^>]*>[\s\S]*?<\/style>/gi) || []).join('\n');
  var size = 90000, chunks = {}, k = 0;
  for (var p = 0; p < out.length; p += size) chunks['CSS_' + (k++)] = out.slice(p, p + size);
  chunks.CSS_N = String(k);
  try { cache.putAll(chunks, 21600); } catch (e) {}
  return out;
}

/**
 * 편집기 미리보기용 실제 블로그 화면 틀
 *  - 블로그 페이지 HTML 을 그대로 받아(테마 CSS·머리글·메뉴·바닥글·테마 스크립트 포함) 블로거 자체 위젯 스크립트·광고만 뺌
 *  - 편집기가 이 틀의 #hp-root(홈) 또는 .post-body(하위 페이지)에 편집 중인 내용을 넣어 실제 사이트와 같은 화면으로 보여 줌
 *  - url: 블로그 안의 경로(/p/xxx.html) · 없으면 홈 · 6시간 보관
 */
function shell_(path, fresh) {
  var base = blogUrl_().replace(/\/$/, '');
  path = /^\/p\/[\w\-%.]+\.html$/.test(path) ? path : '/';
  var url = base + path, key = 'SHELL_' + Utilities.base64EncodeWebSafe(Utilities.computeDigest(Utilities.DigestAlgorithm.MD5, url)).slice(0, 20);
  var cache = CacheService.getScriptCache();
  if (!fresh) { var hit = bigGet_(cache, key); if (hit) return { ok: true, html: hit, url: url }; }
  var html;
  try { html = fetchText_(url + (url.indexOf('?') < 0 ? '?' : '&') + 'sl-shell=' + Date.now()); } catch (e) { return { ok: false, error: String(e.message || e) }; }
  html = html
    .replace(/<script\b[^>]*\bsrc=["'][^"']*(blogger\.com|blogblog\.com|googlesyndication|googletagmanager|google-analytics|gstatic\.com\/[^"']*blogger|adservice)[^"']*["'][^>]*>\s*<\/script>/gi, '')
    .replace(/<script\b[^>]*>(?:(?!<\/script>)[\s\S])*?(_WidgetManager|BLOG_|adsbygoogle|gtag\(|_gaq)(?:(?!<\/script>)[\s\S])*?<\/script>/gi, '')
    .replace(/<ins\b[^>]*adsbygoogle[\s\S]*?<\/ins>/gi, '')
    .replace(/<iframe\b[^>]*(navbar|blogger\.com)[\s\S]*?<\/iframe>/gi, '');
  bigPut_(cache, key, html, 21600);
  return { ok: true, html: html, url: url };
}
/** 9만 자보다 큰 글을 캐시에 나눠 보관 */
function bigPut_(cache, key, text, sec) {
  var size = 90000, chunks = {}, k = 0;
  for (var p = 0; p < text.length; p += size) chunks[key + '_' + (k++)] = text.slice(p, p + size);
  chunks[key + '_N'] = String(k);
  try { cache.putAll(chunks, sec); } catch (e) {}
}
function bigGet_(cache, key) {
  var n = Number(cache.get(key + '_N') || 0); if (!n) return '';
  var names = []; for (var i = 0; i < n; i++) names.push(key + '_' + i);
  var parts = cache.getAll(names), all = '';
  for (var j = 0; j < n; j++) { if (parts[key + '_' + j] == null) return ''; all += parts[key + '_' + j]; }
  return all;
}

/** 공개 설정: 홈 화면이 쓰는 값만 (AI 지시문·키 제외) */
