/* ─────────── 로그인 ─────────── */
function login_(req) {
  var id = String(req.id || '').trim().toLowerCase();
  var cache = CacheService.getScriptCache(), key = 'FAIL_' + id;
  var fails = Number(cache.get(key) || 0);
  if (fails >= LOGIN_MAX_FAIL) return { ok: false, code: 'LOCKED', error: '로그인을 ' + LOGIN_MAX_FAIL + '번 틀려 ' + LOGIN_LOCK_MIN + '분 동안 잠겼습니다.' };
  var good = id && id === PROPS.getProperty('ADMIN_ID') && checkPassword_(req.pw);
  if (!good) {
    cache.put(key, String(fails + 1), LOGIN_LOCK_MIN * 60);
    return { ok: false, code: 'LOGIN', error: '아이디 또는 비밀번호가 맞지 않습니다.', left: LOGIN_MAX_FAIL - fails - 1 };
  }
  cache.remove(key);
  var exp = Date.now() + TOKEN_HOURS * 3600e3;
  return { ok: true, token: makeToken_({ u: id, v: tokenVer_(), exp: exp }, PROPS.getProperty('TOKEN_SECRET')), exp: exp };
}

function withAuth_(req, fn) {
