function resetConfirm_(req) {
  var lock = LockService.getScriptLock(); lock.waitLock(10000);
  try {
    var r = safeJson_(PROPS.getProperty('RESET'));
    if (!r || r.exp < Date.now()) return { ok: false, code: 'EXPIRED', error: '인증 번호가 만료되었습니다. 다시 요청하세요.' };
    if (r.n >= RESET_MAX_TRY) { PROPS.deleteProperty('RESET'); return { ok: false, code: 'EXPIRED', error: '인증 번호를 ' + RESET_MAX_TRY + '번 틀렸습니다. 다시 요청하세요.' }; }
    if (pwHash_(String(req.code || ''), r.s).slice(0, 32) !== r.h) {
      r.n++; PROPS.setProperty('RESET', JSON.stringify(r));
      return { ok: false, code: 'CODE', error: '인증 번호가 맞지 않습니다.', left: RESET_MAX_TRY - r.n };
    }
    if (!req.newPw || String(req.newPw).length < 8) return { ok: false, code: 'PW', error: '새 비밀번호는 8자 이상이어야 합니다.' };
    setPassword_(req.newPw);
    PROPS.deleteProperty('RESET');
    bumpTokenVer_();
    CacheService.getScriptCache().remove('FAIL_' + PROPS.getProperty('ADMIN_ID'));
    return { ok: true, id: PROPS.getProperty('ADMIN_ID') };
  } finally { lock.releaseLock(); }
}

/* ═════════════════════════════ 가젯 설정 읽기 ═════════════════════════════ */

/** 홈 화면 HTML 의 설정 가젯 4개 (10분 캐시) */
function readGadgets_(fresh) {
