function readGadgetJson_(html, id) {
  var t = readGadgetText_(html, id);
  if (t === null) return null;
  try { return JSON.parse(t); } catch (e) { return null; }
}
function readGadgetText_(html, id) {
  var re = new RegExp('<script[^>]*\\bid=["\']' + id + '["\'][^>]*>([\\s\\S]*?)<\\/script>', 'i');
  var m = String(html || '').match(re);
