}

/* ═════════════════════════════ 비밀번호 · 토큰 ═════════════════════════════ */

function setPassword_(pw) {
  var salt = newSecret_();
  PROPS.setProperties({ ADMIN_SALT: salt, ADMIN_HASH: pwHash_(pw, salt) });
}
function checkPassword_(pw) {
  var h = PROPS.getProperty('ADMIN_HASH'), s = PROPS.getProperty('ADMIN_SALT');
  return !!(pw && h && s) && safeEq_(pwHash_(pw, s), h);
}
/** HMAC-SHA256 1,000번 반복 */
function pwHash_(pw, salt) {
  var h = String(pw);
  for (var i = 0; i < 1000; i++) h = hex_(Utilities.computeHmacSha256Signature(h + ':' + i, salt, Utilities.Charset.UTF_8));
  return h;
}
function makeToken_(obj, secret) {
  var p = Utilities.base64EncodeWebSafe(JSON.stringify(obj)).replace(/=+$/, '');
  return p + '.' + sign_(p, secret);
}
function checkToken_(tok, secret) {
  var parts = String(tok || '').split('.');
  if (!secret || parts.length !== 2 || !safeEq_(sign_(parts[0], secret), parts[1])) return null;
  try {
    var obj = JSON.parse(Utilities.newBlob(Utilities.base64DecodeWebSafe(parts[0] + '==='.slice((parts[0].length + 3) % 4))).getDataAsString('UTF-8'));
    return obj.exp > Date.now() ? obj : null;
  } catch (e) { return null; }
}
function tokenVer_() { return Number(PROPS.getProperty('TOKEN_VER') || 1); }
function bumpTokenVer_() { PROPS.setProperty('TOKEN_VER', String(tokenVer_() + 1)); }
function sign_(s, secret) { return Utilities.base64EncodeWebSafe(Utilities.computeHmacSha256Signature(s, secret)).replace(/=+$/, ''); }
function safeEq_(a, b) {
  a = String(a); b = String(b);
  if (a.length !== b.length) return false;
  var d = 0; for (var i = 0; i < a.length; i++) d |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return d === 0;
}
function newSecret_() { return Utilities.base64EncodeWebSafe(Utilities.getUuid() + Utilities.getUuid()).replace(/=+$/, ''); }
function resetCode_() { return String(100000 + Math.floor(Math.random() * 900000)); }
function hex_(bytes) { return bytes.map(function (b) { return ('0' + (b & 255).toString(16)).slice(-2); }).join(''); }

/* ═════════════════════════════ Blogger · 공통 ═════════════════════════════ */

function blogId_(fresh) {
  var id = !fresh && PROPS.getProperty('BLOG_ID');
  if (id) return id;
  var res = UrlFetchApp.fetch('https://www.googleapis.com/blogger/v3/blogs/byurl?fields=id&url=' + encodeURIComponent(blogUrl_()),
    { headers: { Authorization: 'Bearer ' + ScriptApp.getOAuthToken() }, muteHttpExceptions: true });
  var d = safeJson_(res.getContentText());
  if (res.getResponseCode() !== 200 || !d || !d.id) throw new Error('HTTP ' + res.getResponseCode() + ' ' + res.getContentText().slice(0, 300));
  PROPS.setProperty('BLOG_ID', d.id);
  return d.id;
}
function blogName_() {
  var n = PROPS.getProperty('BLOG_NAME');
  if (n) return n;
  if (!PROPS.getProperty('BLOG_ID')) return '사이트루미';          // 설치 전
  try { n = api_('get', '', null, { fields: 'name' }).name; } catch (e) { return '사이트루미'; }
  PROPS.setProperty('BLOG_NAME', n);
  return n;
}
function api_(method, path, payload, query) {
  var url = 'https://www.googleapis.com/blogger/v3/blogs/' + blogId_() + path;
  if (query) url += '?' + Object.keys(query).map(function (k) { return encodeURIComponent(k) + '=' + encodeURIComponent(query[k]); }).join('&');
  var opt = { method: method, headers: { Authorization: 'Bearer ' + ScriptApp.getOAuthToken() }, muteHttpExceptions: true };
  if (payload) { opt.contentType = 'application/json'; opt.payload = JSON.stringify(payload); }
  var isWrite = method !== 'get';
  var waited = 0, res, code;
  for (var i = 0; i < 6; i++) {
    /* 블로거 쓰기는 몰아서 보내면 429(한도 초과) → 쓰기 사이 최소 간격 */
    if (isWrite) {
      var gap = Date.now() - LAST_WRITE_;
      if (gap < WRITE_GAP_MS) Utilities.sleep(WRITE_GAP_MS - gap);
      LAST_WRITE_ = Date.now();
    }
    res = UrlFetchApp.fetch(url, opt); code = res.getResponseCode();
    if (code >= 200 && code < 300) { var t = res.getContentText(); return t ? JSON.parse(t) : {}; }
    if ((code === 429 || code >= 500) && i < 5) {
      var ms = (code === 429 ? 5000 : 1000) * Math.pow(2, i) + Math.floor(Math.random() * 1000);
      if (waited + ms > 100000) break;
      Utilities.sleep(ms); waited += ms; continue;
    }
    break;
  }
  throw new Error('BLOGGER_' + code + ': ' + res.getContentText().slice(0, 300));
}
var LAST_WRITE_ = 0;
var WRITE_GAP_MS = 2000;
function tryPatch_(path, body) { try { return api_('patch', path, body); } catch (e) { if (/_404/.test(e.message)) return null; throw e; } }
var WEBAPP_RE_ = /^https:\/\/script\.google\.com\/(a\/[^/]+\/)?macros\/s\/[\w-]+\/exec$/;
function webAppUrl_() {
  var u = String(PROPS.getProperty('WEBAPP_URL') || CONFIG.WEBAPP_URL || '').trim();
  if (u) return u;
  try { u = ScriptApp.getService().getUrl() || ''; } catch (e) { u = ''; }
  return WEBAPP_RE_.test(u) ? u : '';
}
/** 웹앱으로 열렸을 때 자기 주소(…/exec)를 기억 */
function rememberWebApp_() {
  try {
    var u = ScriptApp.getService().getUrl() || '';
    if (WEBAPP_RE_.test(u) && PROPS.getProperty('WEBAPP_URL') !== u) PROPS.setProperty('WEBAPP_URL', u);
  } catch (e) {}
}
/** 블로그 주소: 설치 때 저장한 값 → (예전 설치) 블로그 번호로 찾아서 저장 */
function blogUrl_() {
  var u = PROPS.getProperty('BLOG_URL') || CONFIG.BLOG_URL || '';
  if (!u && PROPS.getProperty('BLOG_ID')) {
    try { u = api_('get', '', null, { fields: 'url' }).url || ''; } catch (e) { u = ''; }
    if (u) { u = u.replace(/^http:/, 'https:').replace(/\/?$/, '/'); PROPS.setProperty('BLOG_URL', u); }
  }
  return u;
}
function callWeb_(url, body) {
  var res = UrlFetchApp.fetch(url, { method: 'post', contentType: 'text/plain;charset=utf-8', payload: JSON.stringify(body), muteHttpExceptions: true, followRedirects: true });
  return safeJson_(res.getContentText());
}
function fetchText_(url) {
  var res = UrlFetchApp.fetch(url, { muteHttpExceptions: true, followRedirects: true });
  if (res.getResponseCode() !== 200) throw new Error('불러오기 실패 ' + res.getResponseCode() + ': ' + url);
  return res.getContentText();
}
function json_(o) { return ContentService.createTextOutput(JSON.stringify(o)).setMimeType(ContentService.MimeType.JSON); }
function safeJson_(t) { try { return JSON.parse(t); } catch (e) { return null; } }
function esc_(s) { return String(s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }
function maskEmail_(e) { var p = String(e || '').split('@'); return p.length < 2 ? '' : p[0].slice(0, 2) + '***@' + p[1]; }

var RESULTS_ = [];
function ok_(cond, name, detail) { RESULTS_.push(!!cond); log_((cond ? '✅ ' : '❌ ') + name + (detail ? '  — ' + detail : '')); }
function done_(t) {
  var bad = RESULTS_.filter(function (x) { return !x; }).length;
  log_(bad ? '⚠️ ' + t + ': ' + bad + '개 확인 필요 (위 ❌)' : '🎉 ' + t + ' 통과');
  RESULTS_ = [];
}
function log_(m) { console.log(m); }

/**
 * 사이트루미 맞춤 코드 (맞춤형 상품 · 판매자 작업분) — 구매자 엔진 쪽
 * ------------------------------------------------------------------------
 *  판매자가 관리자 모드 「[맞춤 코드]」 글에 CSS·JS·첫 화면 HTML·섹션 HTML 을 쓰고 「보내기」를 누르면
 *  판매자 GAS 가 서명해서 이 웹앱(a:'customCert')으로 보냄 → 서명 확인 뒤 보관
 *   - 초안(site.customDraft): 편집기 미리보기에서만 보임 → 사장님(또는 판매자)이 「공개」
 *   - 공개(site.custom): 모든 페이지에 들어감 · 바로 전 공개본(site.customPrev)으로 「되돌리기」 가능
 *   - JS 는 30KB 까지, 테마가 오류 상자(try/catch) 안에서 실행 → 오류가 나도 홈페이지는 그대로
 *  편집기에서 보낸 사이트 데이터의 맞춤 코드 값은 쓰지 않음 (서명된 것만)
 */
var CUSTOM_LIMIT = { css: 60000, js: 30000, html: 30000, total: 150000 };

/** 묶음 점검: 크기·형식 → 정리된 묶음 (틀리면 오류 문구) */
function customClean_(b) {
  if (!b || typeof b !== 'object') return '맞춤 코드 형식이 올바르지 않습니다.';
  var out = { css: String(b.css || ''), js: String(b.js || ''), hero: String(b.hero || ''), sections: {}, note: String(b.note || '').slice(0, 200), rev: String(b.rev || '').slice(0, 40) };
  if (out.css.length > CUSTOM_LIMIT.css) return 'CSS 가 너무 큽니다 (' + CUSTOM_LIMIT.css / 1000 + 'KB 까지).';
  if (out.js.length > CUSTOM_LIMIT.js) return 'JS 가 너무 큽니다 (' + CUSTOM_LIMIT.js / 1000 + 'KB 까지).';
  if (out.hero.length > CUSTOM_LIMIT.html) return '첫 화면 HTML 이 너무 큽니다.';
  Object.keys(b.sections || {}).slice(0, 30).forEach(function (k) { var id = String(k).replace(/[^\w-]/g, '').slice(0, 40); if (id) out.sections[id] = String(b.sections[k] || '').slice(0, CUSTOM_LIMIT.html); });
  if (JSON.stringify(out).length > CUSTOM_LIMIT.total) return '맞춤 코드 전체가 너무 큽니다.';
  return out;
}

var CUSTOM_WRITE_ = false;     // 맞춤 코드 함수가 저장할 때만 true (slSave_ 가 편집기 값을 덮어쓰지 않게)

/** 판매자 서명 묶음 받기 */
function customApply_(cert) {
  var p = signedPayload_(cert);
  if (!p || p.v !== 1 || p.kind !== 'custom') return { ok: false, error: '판매자 서명이 올바르지 않습니다.' };
  if (String(p.blogId) !== String(PROPS.getProperty('BLOG_ID') || '')) return { ok: false, error: '다른 사이트의 맞춤 코드입니다.' };
  var last = PROPS.getProperty('CUSTOM_IAT') || '';
  if (!p.iat || String(p.iat) <= last) return { ok: false, error: '이미 받은 것보다 오래된 맞춤 코드입니다.' };   // 예전 묶음을 다시 보내 되돌리는 것 막기
  var b = customClean_(p.b); if (typeof b === 'string') return { ok: false, error: b };
  b.rev = String(p.iat || new Date().toISOString()); b.at = new Date().toISOString();
  var site = slLoad_(); if (!site) return { ok: false, error: '사이트가 아직 없습니다.' };
  if (site.customDraft && site.customDraft.rev === b.rev && !p.publish) return { ok: true, same: true };
  site.customDraft = b;
  if (p.publish) { if (site.custom) site.customPrev = site.custom; site.custom = b; delete site.customDraft; }
  var res = customSave_(site);
  if (res.ok) PROPS.setProperty('CUSTOM_IAT', String(p.iat));
  return res.ok ? { ok: true, published: !!p.publish, rev: b.rev } : res;
}

/** 편집기: 초안 공개 · 되돌리기 · 끄기 */
function customAction_(act) {
  var site = slLoad_(); if (!site) return { ok: false, error: '사이트가 없습니다.' };
  if (act === 'publish') {
    if (!site.customDraft) return { ok: false, error: '공개할 초안이 없습니다.' };
    if (site.custom) site.customPrev = site.custom;
    site.custom = site.customDraft; delete site.customDraft;
  } else if (act === 'rollback') {
    if (!site.customPrev) return { ok: false, error: '되돌릴 이전 버전이 없습니다.' };
    var cur = site.custom; site.custom = site.customPrev; site.customPrev = cur || null;
  } else if (act === 'off') {
    if (site.custom) site.customPrev = site.custom;
    delete site.custom;
  } else if (act === 'discard') {
    delete site.customDraft;
  } else return { ok: false, error: '알 수 없는 요청' };
  var res = customSave_(site);
  return res.ok ? { ok: true, site: slLoad_() } : res;
}

function customSave_(site) {
  CUSTOM_WRITE_ = true;
  try { return slSave_(site, null); } finally { CUSTOM_WRITE_ = false; }
}

/** slSave_ 안에서: 편집기가 보낸 맞춤 코드 값 대신 저장된 값 유지 */
function customKeep_(site, cur) {
  if (CUSTOM_WRITE_) return;
  ['custom', 'customDraft', 'customPrev'].forEach(function (k) { if (cur && cur[k]) site[k] = cur[k]; else delete site[k]; });
}

/**
 * 사진 보관 — 구글 드라이브를 쓰지 않고 블로그 정적 페이지에 보관
 * ------------------------------------------------------------------------
 *  · 편집기가 휴대폰 사진을 WebP(안 되면 JPEG)로 줄여서 보냄 (긴 변 1600px 이하, 600KB 이하)
 *  · 사진 1장 = 정적 페이지 1개 (제목 sl-img, 검색 제외) : <div class="sl-store" data-kind="img">~~SLB~~img:가로x세로:data:image/…~~SLE~~</div>
 *  · 사이트 데이터에는 'slimg:페이지번호' 만 저장 → 데이터가 가벼움
 *  · 홈페이지: 첫 화면 사진·명함 사진은 페이지에 바로 넣고(빠른 첫 화면), 나머지는 보일 때 불러옴(테마 [S16])
 */
var IMG_MAX_CHARS = 820000;      // data URI 기준 약 600KB

/** 편집기 → 사진 올리기 */
function slImgPut_(req) {
  var data = String(req.data || '');
  var m = /^data:image\/(webp|jpeg|png);base64,[A-Za-z0-9+\/=]+$/.exec(data);
  if (!m) return { ok: false, error: '사진 형식이 맞지 않습니다. (WebP · JPEG · PNG)' };
  if (data.length > IMG_MAX_CHARS) return { ok: false, error: '사진이 너무 큽니다. 다시 골라 주세요.' };
  var w = Math.max(1, Math.min(4000, Number(req.w) || 0)), h = Math.max(1, Math.min(4000, Number(req.h) || 0));
  try {
    var page = api_('post', '/pages/', { title: 'sl-img', content: slStoreWrap_('img', 'img:' + w + 'x' + h + ':' + data) }, { isDraft: 'false' });
    imgCachePut_(page.id, data);
    return { ok: true, id: String(page.id), ref: 'slimg:' + page.id, w: w, h: h };
  } catch (e) {
    if (/BLOGGER_429/.test(e.message)) return { ok: false, code: 'RATE', error: '사진 올리기가 잠시 몰렸어요. 1~2분 뒤 다시 올려 주세요.' };
    throw e;
  }
}

/** 편집기 미리보기용: 사진 데이터 여러 장 */
function slImgGet_(req) {
  var ids = (req.ids || []).map(String).filter(function (x) { return /^\d+$/.test(x); }).slice(0, 40);
  var out = {};
  ids.forEach(function (id) { var d = imgData_(id); if (d) out[id] = d; });
  return { ok: true, images: out };
}

/** 사진 한 장 데이터 (캐시 → 블로그 페이지) */
function imgData_(id) {
  var d = imgCacheGet_(id);
  if (d) return d;
  try {
    var page = api_('get', '/pages/' + id, null, { view: 'ADMIN', fields: 'content' });
    var p = String(slStoreUnwrap_(page.content) || '');
    var m = /^img:\d+x\d+:(data:image\/(webp|jpeg|png);base64,[A-Za-z0-9+\/=]+)$/.exec(p);
    if (!m) return '';
    imgCachePut_(id, m[1]);
    return m[1];
  } catch (e) { return ''; }
}

/** 캐시(6시간): 한 값 100KB 제한 → 90KB 씩 나눠 보관 */
function imgCachePut_(id, data) {
  try {
    var c = CacheService.getScriptCache(), n = Math.ceil(data.length / 90000), o = {};
    for (var i = 0; i < n; i++) o['IMG_' + id + '_' + i] = data.slice(i * 90000, (i + 1) * 90000);
    o['IMG_' + id] = String(n);
    c.putAll(o, 21600);
  } catch (e) {}
}
function imgCacheGet_(id) {
  try {
    var c = CacheService.getScriptCache(), n = Number(c.get('IMG_' + id) || 0);
    if (!n) return '';
    var keys = []; for (var i = 0; i < n; i++) keys.push('IMG_' + id + '_' + i);
    var all = c.getAll(keys), s = '';
    for (var j = 0; j < n; j++) { if (all[keys[j]] == null) return ''; s += all[keys[j]]; }
    return s;
  } catch (e) { return ''; }
}

/** 발행할 때 바로 넣을 사진: 홈 첫 화면 사진 + 명함 프로필·커버·로고 (첫 화면이 사진을 기다리지 않게) */
function slEagerImages_(site) {
  var refs = [], S = site.sections || {}, add = function (v) { var r = SL_RENDER.imgRef(v); if (r && refs.indexOf(r) < 0) refs.push(r); };
  var home = (site.pages || []).filter(function (p) { return p.id === 'home'; })[0];
  (home ? home.sections : []).forEach(function (id) { var s = S[id]; if (s && s.type === 'hero') add((s.data || {}).image); });
  var cd = (S.card || {}).data || {};
  add(cd.photo); add(cd.cover); add(cd.logo);
  var map = { __budget: 420000 };       // 홈은 base64 로 한 번 더 감싸므로 블로거 1MB 한도 안에 넉넉히
  refs.slice(0, 6).forEach(function (r) { var d = imgData_(r); if (d) map[r] = d; });
  return map;
}

/**
 * 사이트루미 문의함 · 방문 기록 v1.0
 *
 *  손님 → slLead_  : 상담 신청 접수 (스팸 방지 → 문의함 저장 → 사장님 이메일)
 *  손님 → slHit_   : 페이지 보기 · 버튼 누름 기록 (날짜별 합계만, 개인정보 없음)
 *  사장님 → slLeads_ / slLeadSet_ / slStats_ : 편집기 대시보드
 *
 * 저장: 스크립트 속성 (구글 드라이브 안 씀)
 *   L_<시각>_<임의>  문의 1건 (최근 LEAD_MAX 건, 보관 기간 지나면 자동 삭제)
 *   ST_<yyyymmdd>    하루 합계 { v: 보기, p: {페이지: 수}, b: {버튼: 수}, r: {경로: 수} }  (STAT_DAYS 일 보관)
 *   PV_<yyyymmdd>    그날 밤 12시 무렵 블로거 '전체 방문 수' (블로거 기준 날짜별 방문 = 다음 날 값 − 그날 값)
 *
 * 방문 수는 블로거 집계가 기준입니다. 블로거 API 는 7일·30일·전체 합계만 주므로
 * 매일 밤 12시(±15분) 자동 실행(STEP8 에서 설치)으로 전체 방문 수를 기록해 날짜별로 나눕니다.
 * 페이지별·경로·버튼은 블로거가 API 로 주지 않아 홈페이지가 직접 센 기록입니다.
 */
var LEAD_MAX = 200;            // 문의 최대 보관 건수 (스크립트 속성 전체 500KB 한도 안에서)
var LEAD_KEEP_DAYS = 365;      // 개인정보처리방침의 기본 보관 기간 (문의 처리 후 1년)
var STAT_DAYS = 90;            // 방문 기록 보관 일수
var PROPS_BUDGET = 400000;     // 스크립트 속성 전체 사용량이 이보다 크면 오래된 문의부터 정리 (구글 한도 500KB)
var HIT_PER_MIN = 240;         // 1분에 받는 방문·버튼 기록 최대 수 (기록 폭주 방지)
var LEAD_PER_MIN = 10;         // 1분에 받는 문의 최대 수 (스팸 방지)
var HIT_TYPES = { call: 1, sms: 1, kakao: 1, map: 1, booking: 1, review: 1, insta: 1, blog: 1, youtube: 1, link: 1, contact: 1, mail: 1, vcard: 1, shareCard: 1, shareHome: 1 };
var REF_TYPES = { naver: 1, google: 1, daum: 1, instagram: 1, kakao: 1, facebook: 1, youtube: 1, direct: 1, etc: 1 };

function dayKey_(d) {
  d = d || new Date();
  return 'ST_' + Utilities.formatDate(d, Session.getScriptTimeZone() || 'Asia/Seoul', 'yyyyMMdd');
}
function clip_(s, n) { return String(s == null ? '' : s).replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g, '').trim().slice(0, n); }

/* ─────────── 손님: 상담 신청 ─────────── */
function slLead_(req) {
  if (req.website) return { ok: true };                                   // 로봇이 채우는 숨은 칸 → 조용히 무시
  var name = clip_(req.name, 40), phone = clip_(req.phone, 30), msg = clip_(req.msg, 1000), page = clip_(req.page, 120);
  var digits = phone.replace(/[^\d]/g, '');
  if (!name || digits.length < 8) return { ok: false, code: 'INPUT', error: '이름과 연락처를 확인해 주세요.' };
  if (!req.agree) return { ok: false, code: 'AGREE', error: '개인정보 수집·이용에 동의해 주세요.' };
  var cache = CacheService.getScriptCache();
  if (cache.get('LD_' + digits)) return { ok: true, dup: true };          // 같은 번호 1분 안 중복 제출
  var n = Number(cache.get('LD_MIN') || 0);
  if (n >= LEAD_PER_MIN) return { ok: false, code: 'BUSY', error: '잠시 후 다시 보내 주세요.' };
  cache.put('LD_MIN', String(n + 1), 60);
  cache.put('LD_' + digits, '1', 60);

  var lead = { t: Date.now(), name: name, phone: SL_RENDER.fmtTel(phone), msg: msg, page: page, st: 'new' };
  var key = 'L_' + lead.t + '_' + Math.random().toString(36).slice(2, 6);
  var lock = LockService.getScriptLock();
  if (lock.tryLock(5000)) {
    try {
      /* 같은 1/1000초에 두 건이 들어와도 순서가 섞이지 않게 */
      var last = leadKeys_()[0], lt = last ? Number(last.split('_')[1]) : 0;
      if (lt >= lead.t) { lead.t = lt + 1; key = 'L_' + lead.t + '_' + key.split('_')[2]; }
      saveLead_(key, lead); pruneLeads_();
    } finally { lock.releaseLock(); }
  } else {
    saveLead_(key, lead);
  }
  addHit_({ b: 'lead' });
  try { mailLead_(lead); } catch (e) { /* 메일 한도 초과여도 문의함에는 남음 */ }
  return { ok: true };
}

/** 문의 저장 — 저장 공간이 꽉 차 실패하면 오래된 문의를 정리하고 한 번 더 (그래도 메일은 감) */
function saveLead_(key, lead) {
  try { PROPS.setProperty(key, JSON.stringify(lead)); }
  catch (e) { try { pruneLeads_(); PROPS.setProperty(key, JSON.stringify(lead)); } catch (e2) {} }
}
function mailLead_(lead) {
  var to = PROPS.getProperty('ADMIN_EMAIL');
  if (!to || MailApp.getRemainingDailyQuota() < 1) return;
  var editor = webAppUrl_();
  var when = Utilities.formatDate(new Date(lead.t), Session.getScriptTimeZone() || 'Asia/Seoul', 'M월 d일 HH:mm');
  var html = '<div style="font-family:sans-serif;font-size:15px;line-height:1.7;color:#1f2937">' +
    '<p style="font-size:18px;font-weight:800;margin:0 0 12px">새 상담 신청이 들어왔어요</p>' +
    '<table style="border-collapse:collapse">' +
    '<tr><td style="padding:4px 16px 4px 0;color:#6b7280">이름</td><td><b>' + esc_(lead.name) + '</b></td></tr>' +
    '<tr><td style="padding:4px 16px 4px 0;color:#6b7280">연락처</td><td><a href="tel:' + esc_(lead.phone.replace(/[^\d+]/g, '')) + '">' + esc_(lead.phone) + '</a></td></tr>' +
    '<tr><td style="padding:4px 16px 4px 0;color:#6b7280">시간</td><td>' + when + '</td></tr>' +
    (lead.page ? '<tr><td style="padding:4px 16px 4px 0;color:#6b7280">페이지</td><td>' + esc_(lead.page) + '</td></tr>' : '') +
    '</table>' + (lead.msg ? '<p style="margin:16px 0;padding:12px 14px;background:#f3f4f6;border-radius:8px;white-space:pre-wrap">' + esc_(lead.msg) + '</p>' : '') +
    (editor ? '<p><a href="' + editor + '" style="color:#2563eb">편집기 › 대시보드에서 문의함 보기</a></p>' : '') + '</div>';
  MailApp.sendEmail({ to: to, subject: '[' + blogName_() + '] 새 상담 신청 — ' + lead.name, htmlBody: html, name: blogName_(), replyTo: to });
}

function leadKeys_() {
  return Object.keys(PROPS.getProperties()).filter(function (k) { return /^L_\d+_/.test(k); })
    .sort(function (a, b) { return Number(b.split('_')[1]) - Number(a.split('_')[1]); });
}
/** 오래된 문의 정리: 보관 기간이 지났거나 최대 건수를 넘은 것 */
function pruneLeads_() {
  var limit = Date.now() - LEAD_KEEP_DAYS * 864e5, keys = leadKeys_();
  keys = keys.filter(function (k, i) { if (i >= LEAD_MAX || Number(k.split('_')[1]) < limit) { PROPS.deleteProperty(k); return false; } return true; });
  /* 스크립트 속성 전체가 한도에 가까우면 처리 끝난 문의 → 오래된 문의 순으로 정리 */
  var all = PROPS.getProperties(), size = JSON.stringify(all).length * 2;
  if (size <= PROPS_BUDGET) return;
  var order = keys.slice().reverse().sort(function (a, b) { return (/"st":"done"/.test(all[b]) ? 1 : 0) - (/"st":"done"/.test(all[a]) ? 1 : 0); });
  for (var i = 0; i < order.length && size > PROPS_BUDGET; i++) { size -= (order[i].length + String(all[order[i]]).length) * 2; PROPS.deleteProperty(order[i]); }
}

/* ─────────── 손님: 방문·버튼 기록 ─────────── */
function slHit_(req) {
  var h = {};
  if (req.k === 'view') {
    h.v = 1; h.p = clip_(req.p, 60) || '/';
    h.r = REF_TYPES[req.r] ? req.r : (req.r ? 'etc' : '');
  } else if (HIT_TYPES[req.k]) h.b = req.k;
  else return { ok: true };
  var cache = CacheService.getScriptCache(), n = Number(cache.get('HIT_MIN') || 0);
  if (n >= HIT_PER_MIN) return { ok: true };            // 몰리면 조용히 건너뜀 (합계 통계라 괜찮음)
  cache.put('HIT_MIN', String(n + 1), 60);
  addHit_(h);
  return { ok: true };
}
function addHit_(h) {
  var lock = LockService.getScriptLock();
  if (!lock.tryLock(2500)) return;                      // 몰릴 때는 한 건 빠져도 괜찮음 (합계 통계)
  try {
    var key = dayKey_(), d = safeJson_(PROPS.getProperty(key)) || { v: 0, p: {}, b: {}, r: {} };
    if (h.v) {
      d.v++;
      if (Object.keys(d.p).length < 30 || d.p[h.p]) d.p[h.p] = (d.p[h.p] || 0) + 1;
      if (h.r) d.r[h.r] = (d.r[h.r] || 0) + 1;
    }
    if (h.b) d.b[h.b] = (d.b[h.b] || 0) + 1;
    PROPS.setProperty(key, JSON.stringify(d));
  } finally { lock.releaseLock(); }
}

/* ─────────── 사장님: 대시보드 ─────────── */
function slLeads_() {
  pruneLeads_();
  var all = PROPS.getProperties();
  return { ok: true, leads: leadKeys_().map(function (k) { var x = safeJson_(all[k]) || {}; x.id = k; return x; }) };
}
function slLeadSet_(req) {
  var id = String(req.id || '');
  if (!/^L_\d+_/.test(id)) return { ok: false, error: '문의를 찾을 수 없습니다.' };
  if (req.del) { PROPS.deleteProperty(id); return { ok: true }; }
  var x = safeJson_(PROPS.getProperty(id)); if (!x) return { ok: false, error: '문의를 찾을 수 없습니다.' };
  x.st = req.st === 'done' ? 'done' : 'new';
  PROPS.setProperty(id, JSON.stringify(x));
  return { ok: true };
}
/* ─────────── 블로거 기준 날짜별 방문 ─────────── */
function blogPageviews_() {
  var pv = api_('get', '/pageviews?range=7DAYS&range=30DAYS&range=all');
  /* 응답의 기간 이름은 요청과 다름: SEVEN_DAYS · THIRTY_DAYS · ALL_TIME (예전 형식 7DAYS·30DAYS·all 도 받음)
     방문이 0 이면 count 칸이 빠져서 옴 → 0 */
  var o = {};
  (pv.counts || []).forEach(function (c) {
    var r = String(c.timeRange || '').toUpperCase(), n = Number(c.count || 0);
    if (/SEVEN|^7/.test(r)) o['7DAYS'] = n;
    else if (/THIRTY|^30/.test(r)) o['30DAYS'] = n;
    else if (/ALL/.test(r)) o.all = n;
  });
  if (pv.counts && pv.counts.length && o.all == null) o.all = 0;
  return o;
}
/** 매일 밤 12시 자동 실행: 오늘 날짜로 블로거 전체 방문 수 기록 (이미 있으면 그대로) */
function slSnapPageviews() {
  var key = 'PV_' + dayKey_().slice(3);
  if (PROPS.getProperty(key)) return;
  var all = blogPageviews_().all;
  if (all == null) return;
  PROPS.setProperty(key, JSON.stringify({ n: all, t: Date.now() }));
  var keep = 'PV_' + dayKey_(new Date(Date.now() - (STAT_DAYS + 1) * 864e5)).slice(3);
  Object.keys(PROPS.getProperties()).forEach(function (k) { if (/^PV_\d{8}$/.test(k) && k < keep) PROPS.deleteProperty(k); });
}
/** 자동 실행 설치 (STEP8 에서 호출) — 이미 있으면 다시 만들지 않음 */
function installSnapTrigger_() {
  var has = ScriptApp.getProjectTriggers().some(function (t) { return t.getHandlerFunction() === 'slSnapPageviews'; });
  if (!has) ScriptApp.newTrigger('slSnapPageviews').timeBased().atHour(0).nearMinute(0).everyDays(1).inTimezone('Asia/Seoul').create();
  return !has;
}
/** 블로거 기준 날짜별 방문: [{ d, v, live }] — 기록이 없는 날은 v = null */
function blogDays_(all, nowAll) {
  var out = [];
  for (var i = 29; i >= 0; i--) {
    var d = dayKey_(new Date(Date.now() - i * 864e5)).slice(3), nx = dayKey_(new Date(Date.now() - (i - 1) * 864e5)).slice(3);
    var a = safeJson_(all['PV_' + d]), b = i === 0 ? (nowAll != null ? { n: nowAll } : null) : safeJson_(all['PV_' + nx]);
    out.push({ d: d, v: a && b ? Math.max(0, b.n - a.n) : null, live: i === 0 });
  }
  return out;
}

/** 최근 30일 날짜별 합계 + 블로거 전체 페이지뷰(7일·30일·전체) + 새 문의 수 */
function slStats_() {
  var all = PROPS.getProperties(), keep = dayKey_(new Date(Date.now() - STAT_DAYS * 864e5));
  Object.keys(all).forEach(function (k) { if (/^ST_\d{8}$/.test(k) && k < keep) PROPS.deleteProperty(k); });
  var days = [];
  for (var i = 29; i >= 0; i--) {
    var dt = new Date(Date.now() - i * 864e5), k = dayKey_(dt);
    days.push({ d: k.slice(3), s: safeJson_(all[k]) || { v: 0, p: {}, b: {}, r: {} } });
  }
  var blog = null;
  try { blog = blogPageviews_(); } catch (e) { blog = null; }
  /* 오늘 기록이 아직 없으면(자동 실행 설치 전 등) 지금 값으로 시작 — 오늘 숫자는 이 시각부터 */
  var todayKey = 'PV_' + dayKey_().slice(3), late = false;
  if (blog && blog.all != null && !all[todayKey]) { all[todayKey] = JSON.stringify({ n: blog.all, t: Date.now(), late: true }); PROPS.setProperty(todayKey, all[todayKey]); late = true; }
  var t0 = safeJson_(all[todayKey]);
  var trig = false; try { trig = ScriptApp.getProjectTriggers().some(function (t) { return t.getHandlerFunction() === 'slSnapPageviews'; }); } catch (e) {}
  var newLeads = Object.keys(all).filter(function (k) { return /^L_\d+_/.test(k) && /"st":"new"/.test(all[k]); }).length;
  return { ok: true, days: days, blog: blog, blogDays: blog ? blogDays_(all, blog.all) : [], todayPartial: !!(t0 && t0.late), trigger: trig, newLeads: newLeads };
}

/**
 * 사이트루미 상품 등급 — 판매자 서명 「등급 증명」 확인 · 주문(입금했어요)
 * ------------------------------------------------------------------------
 *  · 등급 증명: 판매자 접수 GAS 가 입금 확인 때 개인키로 서명해서 이 엔진 웹앱(a:'planCert')으로 보내 줌.
 *    엔진은 아래 공개키로 확인만 하고 스크립트 속성 PLAN_CERT 에 보관 → 블로그 ID 가 맞을 때만 그 등급의 기능을 켬.
 *    속성·데이터를 손으로 고쳐도 서명이 맞지 않으면 무료로 동작.
 *  · 공개키는 판매자 빌드 도구가 tools/engine.config.json 의 planKey 로 넣어 줌 (비어 있으면 개발용: 속성 PLAN_TIER).
 *  · 가격·계좌는 기본값 + 엔진 버전 정보(manifest.prices · manifest.account)로 판매자가 바꿀 수 있음.
 */
var PLAN_PUB_N = '';    // 판매자 공개키 (빌드 때 자동으로 채움)
var PLAN_DEFAULT = {
  prices: { basic: 99000, standard: 199000, premium: 299000, custom: 549000 },
  options: { sensitive: { name: '민감업종 점검', price: 50000 } },
  account: { bank: '케이뱅크', number: '100 154 306012', holder: '박은주' },
  vat: 0.1
};
var PLAN_ORDER_ = ['free', 'basic', 'standard', 'premium', 'custom'];
var PLAN_NAMES_ = { free: '무료', basic: '기본', standard: '표준', premium: '프리미엄', custom: '맞춤형' };

/* ───── RSA 서명 확인 (BigInt) ───── */
function planModPow_(b, e, m) { var r = BigInt(1); b %= m; while (e > BigInt(0)) { if (e & BigInt(1)) r = (r * b) % m; e >>= BigInt(1); b = (b * b) % m; } return r; }
function planEncode_(text, k) {
  var h = Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, text, Utilities.Charset.UTF_8)
    .map(function (b) { return ('0' + (b & 255).toString(16)).slice(-2); }).join('');
  var t = '3031300d060960864801650304020105000420' + h, ps = '';
  for (var i = 0; i < k - t.length / 2 - 3; i++) ps += 'ff';
  return BigInt('0x0001' + ps + '00' + t);
}
/** 판매자 서명 확인 → 내용 (틀리면 null) · 등급 증명·맞춤 코드 공용 */
function signedPayload_(cert) {
  try {
    var parts = String(cert || '').trim().split('.');
    if (parts.length !== 2 || !PLAN_PUB_N || !/^[0-9a-f]+$/i.test(parts[1])) return null;
    var n = BigInt('0x' + PLAN_PUB_N), s = BigInt('0x' + parts[1]);
    if (s >= n || planModPow_(s, BigInt(65537), n) !== planEncode_(parts[0], PLAN_PUB_N.length / 2)) return null;
    var b64 = parts[0].replace(/-/g, '+').replace(/_/g, '/'); while (b64.length % 4) b64 += '=';
    return JSON.parse(Utilities.newBlob(Utilities.base64Decode(b64)).getDataAsString('UTF-8'));
  } catch (e) { return null; }
}
/** 등급 증명 확인 → 내용 (틀리면 null) */
function planVerify_(cert) {
  var p = signedPayload_(cert);
  return p && p.v === 1 && !p.kind && PLAN_NAMES_[p.tier] && !p.test ? p : null;
}

/** 이 사이트의 등급 (Store.gs 저장·편집기 불러오기에서 씀) */
function slPlan_() {
  if (!PLAN_PUB_N) {                                       // 개발용 (공개키 없는 빌드)
    var t = String(PROPS.getProperty('PLAN_TIER') || 'free');
    return { tier: PLAN_NAMES_[t] ? t : 'free' };
  }
  var p = planVerify_(PROPS.getProperty('PLAN_CERT'));
  if (!p || String(p.blogId) !== String(PROPS.getProperty('BLOG_ID') || '')) return { tier: 'free' };
  return { tier: p.tier, opts: p.opts || [], no: p.no || '', iat: p.iat || '' };
}

/** 증명 받기 (판매자 GAS 가 보냄 · 또는 편집기 붙여넣기) → 보관하고 사이트를 다시 발행 */
function planApply_(cert) {
  var p = planVerify_(cert);
  if (!p) return { ok: false, error: '등급 증명이 올바르지 않습니다.' };
  if (String(p.blogId) !== String(PROPS.getProperty('BLOG_ID') || '')) return { ok: false, error: '다른 사이트의 등급 증명입니다.' };
  var cur = planVerify_(PROPS.getProperty('PLAN_CERT'));
  if (cur && String(cur.blogId) === String(p.blogId) && PLAN_ORDER_.indexOf(cur.tier) > PLAN_ORDER_.indexOf(p.tier)) return { ok: false, error: '이미 더 높은 등급이 적용되어 있습니다.' };
  if (cur && cur.tier === p.tier && String(cur.iat || '') > String(p.iat || '')) return { ok: false, error: '이미 더 새 등급 증명이 적용되어 있습니다.' };   // 예전 증명으로 옵션이 빠지는 것 막기
  PROPS.setProperty('PLAN_CERT', String(cert).trim());
  PROPS.deleteProperty('PLAN_ORDER');
  var site = null;
  try { site = slLoad_(); if (site) slSave_(site, null); } catch (e) {}   // 유료 기능을 넣어 다시 발행
  try { updateReport_(CORE_VER, 'plan-' + p.tier); } catch (e) {}
  return { ok: true, tier: p.tier, name: PLAN_NAMES_[p.tier], republished: !!site };
}

/** 가격·계좌: 기본값 + 판매자 manifest */
function planConfig_() {
  var c = JSON.parse(JSON.stringify(PLAN_DEFAULT)), m = null;
  try { m = updateManifest_(false); } catch (e) {}
  if (m) {
    if (m.prices) Object.keys(c.prices).forEach(function (k) { if (Number(m.prices[k]) > 0) c.prices[k] = Number(m.prices[k]); });
    if (m.options) Object.keys(m.options).forEach(function (k) { c.options[k] = m.options[k]; });
    if (m.account && m.account.number) c.account = m.account;
    c.orderUrl = m.order || m.report || '';
  }
  return c;
}

/** 편집기 「상품」 화면 정보 */
function planInfo_() {
  var pl = slPlan_(), c = planConfig_(), ord = null;
  try { ord = JSON.parse(PROPS.getProperty('PLAN_ORDER') || 'null'); } catch (e) {}
  var site = null; try { site = slLoad_(); } catch (e) {}
  return { ok: true, tier: pl.tier, tierName: PLAN_NAMES_[pl.tier], opts: pl.opts || [], no: pl.no || '', iat: pl.iat || '',
           prices: c.prices, options: c.options, account: c.account, vat: c.vat, canOrder: !!c.orderUrl, order: ord,
           sensitive: site ? !!SL_RENDER.legalKind(site) : false, names: PLAN_NAMES_ };
}

/** 「입금했어요」: 주문을 판매자에게 보냄 (적용은 판매자가 입금 확인할 때) */
function planOrder_(req) {
  var c = planConfig_(), pl = slPlan_(), tier = String(req.tier || '');
  if (!c.orderUrl) return { ok: false, error: '판매자 주문 주소가 아직 설정되지 않았습니다. 판매자에게 문의해 주세요.' };
  if (!c.prices[tier]) return { ok: false, error: '상품을 골라 주세요.' };
  if (PLAN_ORDER_.indexOf(tier) <= PLAN_ORDER_.indexOf(pl.tier)) return { ok: false, error: '이미 같거나 더 높은 상품을 쓰고 있습니다.' };
  var payer = String(req.payer || '').trim().slice(0, 30), phone = String(req.phone || '').replace(/[^\d-]/g, '').slice(0, 20);
  if (!payer) return { ok: false, field: 'payer', error: '입금자명을 넣어 주세요.' };
  if (phone.replace(/\D/g, '').length < 9) return { ok: false, field: 'phone', error: '연락받을 전화번호를 넣어 주세요.' };
  /* 금액은 서버에서 다시 계산 (화면 값은 믿지 않음) */
  var base = c.prices[tier] - (c.prices[pl.tier] || 0), opts = [];
  (req.opts || []).forEach(function (k) { if (c.options[k] && (pl.opts || []).indexOf(c.options[k].name) < 0) { base += Number(c.options[k].price) || 0; opts.push(k); } });
  var tax = req.tax && req.tax.bizNo ? { bizNo: String(req.tax.bizNo).slice(0, 20), company: String(req.tax.company || '').slice(0, 60), owner: String(req.tax.owner || '').slice(0, 30), email: String(req.tax.email || '').slice(0, 80) } : null;
  var amount = tax ? Math.round(base * (1 + c.vat)) : base;
  var order = { blogId: PROPS.getProperty('BLOG_ID') || '', blog: blogUrl_(), webapp: webAppUrl_(), name: blogName_(), tier: tier, from: pl.tier,
                opts: opts.map(function (k) { return c.options[k].name || k; }), amount: amount, payer: payer, phone: phone, tax: tax };
  var res;
  try {
    var r = UrlFetchApp.fetch(c.orderUrl, { method: 'post', contentType: 'text/plain', payload: JSON.stringify({ a: 'order', order: order }), muteHttpExceptions: true, followRedirects: true });
    res = safeJson_(r.getContentText());
  } catch (e) { res = null; }
  if (!res || !res.ok) return { ok: false, error: (res && res.msg) || '판매자에게 주문을 보내지 못했습니다. 잠시 뒤 다시 눌러 주세요.' };
  var ord = { no: res.no, tier: tier, amount: amount, payer: payer, at: new Date().toISOString() };
  PROPS.setProperty('PLAN_ORDER', JSON.stringify(ord));
  return { ok: true, order: ord };
}

