/** 업종 목록 (처음 세팅 화면용): 업종군별로 묶어서 */
function slIndustryList() {
  var out = {};
  Object.keys(SL_INDUSTRIES).forEach(function (k) {
    var x = SL_INDUSTRIES[k], f = SL_FAMILIES[x.f];
    (out[x.f] = out[x.f] || { name: f.name, items: [] }).items.push({ id: k, name: x.name });
  });
  return out;
}

/**
 * 처음 세팅 질문의 답 → 사이트 데이터
 * answers: { industry, name, nameEn, area, address, audience[], tagline, strengths[], years, credentials, staff,
 *            services[{name,price,desc}], priceMode('exact'|'from'|'ask'), photos{hero,gallery[]},
 *            hours{mon..sun}, hoursNote, parking, directions, contacts[{t,v}], mainAction,
 *            skin, hero, color, phone, email, smsText, variant, teamless }
 */
/* 모든 사이트에 공통으로 붙는 페이지: 메뉴에는 안 나오고 바닥글·명함에서 연결 */
var SL_CORE_PAGES = [
  { id: 'card',    slug: 'card',    title: '모바일 명함',     desc: '연락처 저장과 보내기', sections: ['card'],    nomenu: true },
  { id: 'terms',   slug: 'terms',   title: '이용약관',       desc: '',                    sections: ['terms'],   nomenu: true },
  { id: 'privacy', slug: 'privacy', title: '개인정보처리방침', desc: '',                    sections: ['privacy'], nomenu: true }
];
function slToday_() {
  var d = new Date();
  return d.getFullYear() + '년 ' + (d.getMonth() + 1) + '월 ' + d.getDate() + '일';
}
/** 예전에 만든 사이트에 명함·약관 페이지가 없으면 채워 넣음 (저장할 때마다 호출, 있는 내용은 건드리지 않음) */
/** 명함 데이터 기본형: 꾸미기 값이 '' 이면 업종 기본 명함 (Render 의 CARD_BY_FAMILY) */
function slCardData_(base, pick) {
  var d = { style: '', shape: '', btn: '', bg: '', font: '', primary: '',
            person: '', role: '', photo: '', cover: '', logo: '', intro: '',
            placeholder: '' };   // 사진이 없을 때 사진 자리에 넣을 문구 (비우면 영문 상호 → '지역 업종')
  Object.keys(base || {}).forEach(function (k) { d[k] = base[k]; });
  Object.keys(pick || {}).forEach(function (k) { if (k in d) d[k] = pick[k]; });   // 처음 세팅 때 고른 명함 스타일
  d.blocks = SL_RENDER.CARD_DEFAULT_BLOCKS.map(function (t) { return { id: t, type: t, on: true, data: {} }; });
  return d;
}
function slEnsureCore(site) {
  if (!site || !site.pages || !site.sections) return site;
  var b = site.biz || (site.biz = {});
  if (!site.industryName && SL_INDUSTRIES[site.industry]) site.industryName = SL_INDUSTRIES[site.industry].name;
  var add = {
    card: { type: 'card', data: slCardData_({ person: b.owner || '' }) },
    terms: { type: 'legal', data: { kind: 'terms', effective: slToday_() } },
    privacy: { type: 'legal', data: { kind: 'privacy', effective: slToday_() } }
  };
  Object.keys(add).forEach(function (k) {
    if (!site.sections[k]) site.sections[k] = { type: add[k].type, ver: SL_RENDER.MODS[add[k].type].ver, data: add[k].data, opt: {} };
  });
  /* v1 명함(링크 목록만 있던 모양) → 블록 모양으로 옮김. 꾸미기 값은 비워 두어 업종 기본 명함으로 */
  var cs = site.sections.card;
  if (cs && !Array.isArray(cs.data.blocks)) {
    var old = cs.data.links || [];
    cs.data = slCardData_(cs.data);
    if (old.length) cs.data.blocks.filter(function (x) { return x.type === 'links'; })[0].data.items = old;
    delete cs.data.links;
    cs.ver = SL_RENDER.MODS.card.ver;
  }
  SL_CORE_PAGES.forEach(function (p) {
    if (!site.pages.some(function (x) { return x.id === p.id; })) site.pages.push(JSON.parse(JSON.stringify(p)));
  });
  return site;
}

function slBuildSite(answers) {
  var a = answers || {};
  var I = SL_INDUSTRIES[a.industry];
  if (!I) throw new Error('업종 없음: ' + a.industry);
  var F = SL_FAMILIES[I.f];
  var C = SL_IND_COPY[a.industry] || {};                     // 업종별 예시 문구 (없으면 업종군 문구)
  var v = Number(a.variant || 0);
  var str = (a.strengths || []).slice(0, 3);
  var tok = {
    '상호': a.name || '우리 가게',
    '지역': a.area || '우리 동네',
    '업종': I.name,
    '대상': (a.audience && a.audience.length ? a.audience.join('·') : '동네 이웃'),
    '대표서비스': (a.services && a.services[0] && a.services[0].name) || I.items[0],
    '주차': a.parking || '방문 전에 전화로 문의해 주시면 주차 방법을 안내해 드립니다.',
    '서비스': I.svc || '서비스 안내',
    '팀': I.team || '함께하는 사람들'
  };
  function fill(x) {
    if (typeof x === 'string') return x.replace(/\{([^}]+)\}/g, function (m, k) { return k in tok ? tok[k] : m; });
    if (Array.isArray(x)) return x.map(fill);
    if (x && typeof x === 'object') { var o = {}; for (var k in x) o[k] = fill(x[k]); return o; }
    return x;
  }
  function pick(list) { list = list || []; return fill(list[v % Math.max(list.length, 1)] || {}); }

  var services = (a.services && a.services.length ? a.services : I.items.slice(0, 3).map(function (n) { return { name: n }; }))
    .map(function (s) { return { name: s.name, desc: s.desc || (!(a.services && a.services.length) && C.desc && C.desc[s.name] ? fill(C.desc[s.name]) : ''), price: s.price || '', image: s.image || '' }; });

  var hero = pick(C.hero || F.copy.hero);
  var about = pick(C.about || F.copy.about);
  /* 자주 묻는 질문: 업종 질문 먼저, 업종군 질문으로 8개까지 (같은 질문은 한 번만) — 짧은 문답이 AI 답변에 인용되기 쉬움 */
  var faqs = [], seen = {};
  (C.faq || []).concat(F.copy.faq).forEach(function (x) { if (!seen[x.q] && faqs.length < 8) { seen[x.q] = 1; faqs.push(x); } });
  var trust = [];
  if (a.years) trust.push({ value: a.years + '년째', label: (a.area || '이 동네') + '에서' });
  if (a.credentials) trust.push({ value: a.credentials, label: '자격과 인증' });
  if (a.staff) trust.push({ value: a.staff + '명', label: '함께하는 사람' });

  var buttons = (a.contacts && a.contacts.length ? a.contacts : [{ t: 'call' }, { t: 'map' }]).map(function (b) {
    return { t: b.t, v: b.v || '', main: b.t === a.mainAction };
  });
  buttons.sort(function (x, y) { return (y.main ? 1 : 0) - (x.main ? 1 : 0); });

  var D = function (type, data, opt) { return { type: type, ver: SL_RENDER.MODS[type].ver, data: data, opt: opt || {} }; };
  var sections = {
    hero:      D('hero', { eyebrow: hero.eyebrow, title: '', lead: a.tagline || hero.lead, image: (a.photos && a.photos.hero) || '' }),
    trust:     D('trust', { items: trust }),
    about:     D('about', { title: about.title, body: about.body, image: '', points: str.map(function (s) { return { title: s, text: SL_STRENGTHS[s] || '' }; }) }),
    services:  D('services', { title: tok['서비스'], priceMode: a.priceMode || 'from', items: services }),
    pricing:   D('pricing', { title: '가격 안내', groups: a.priceMode === 'ask' ? [] : [{ name: '', rows: services.filter(function (s) { return s.price; }).map(function (s) { return { name: s.name, price: s.price }; }) }] }),
    process:   D('process', fill(C.process || F.copy.process)),
    gallery:   D('gallery', { title: '', cols: 3, items: ((a.photos && a.photos.gallery) || []).map(function (src) { return { src: src }; }) }),
    team:      D('team', { title: tok['팀'], items: [] }),
    reviews:   D('reviews', { items: [] }),
    faq:       D('faq', { items: fill(faqs) }),
    location:  D('location', {}),
    contact:   D('contact', { form: true }),
    cta:       D('cta', pick(C.cta || F.copy.cta)),
    pagelinks: D('pagelinks', {}),
    card:      D('card', slCardData_({ person: a.owner || '', role: a.role || '', photo: a.profilePhoto || '', intro: '' }, a.card)),   // 소개 글을 비워 두면 홈페이지 첫 화면 문구를 따라감
    terms:     D('legal', { kind: 'terms', effective: a.effective || slToday_() }),
    privacy:   D('legal', { kind: 'privacy', effective: a.effective || slToday_(), retention: '', officer: '', officerPhone: '', officerEmail: '' })
  };

  var pages = F.pages.map(function (p) {
    return { id: p.id, slug: p.slug || '', title: fill(p.title), desc: fill(p.desc || ''), sections: p.sections.slice(),
             hidden: (p.id === 'team' && !!a.teamless) };
  }).concat(SL_CORE_PAGES.map(function (p) { return JSON.parse(JSON.stringify(p)); }));

  var built = {
    v: 1, rev: 0, core: SL_RENDER.VERSION,
    industry: a.industry, industryName: I.name, family: I.f, schemaType: I.type,
    biz: {
      name: a.name || '', nameEn: a.nameEn || '', area: a.area || '', address: a.address || '',
      phone: SL_RENDER.fmtTel(a.phone || ''), email: a.email || '', smsText: a.smsText || '',
      owner: a.owner || '', bizNo: a.bizNo || '', mailOrderNo: a.mailOrderNo || '',
      hours: a.hours || {}, hoursNote: a.hoursNote || '', parking: a.parking || '', directions: a.directions || ''
    },
    style: {
      skin: a.skin || I.skin || F.skin,
      hero: a.hero || I.hero || F.hero,
      color: a.color || '',                   // 비우면 디자인 스타일의 기본 색
      font: 'pretendard', anim: 'up', heroAnim: 'rise'
    },
    buttons: buttons,
    pages: pages,
    sections: sections,
    defaults: Object.keys(sections).filter(function (k) { return k !== 'terms' && k !== 'privacy'; })          // 아직 '예시 문구' 상태인 섹션 (편집하면 목록에서 빠짐)
  };
  /* 효과 기본값: 민감업종은 「차분하게」, 나머지는 「세련되게」 (모두 가벼운 무료 효과) */
  return SL_RENDER.applyFxPreset(built, SL_RENDER.legalKind(built) ? 'calm' : 'refined');
}

/**
 * 사이트루미 공용 렌더러 v1.0 — GAS(정적 페이지 생성)와 브라우저(편집 미리보기)가 같은 코드를 씁니다.
 * 이 파일에는 GAS 전용 기능(PropertiesService 등)을 쓰지 않습니다.
 *
 * site 데이터 → 페이지별 HTML (자바스크립트 없이 읽히는 검색·AI 노출용)
 * 모듈(섹션 종류)마다 ver 가 있고, 사이트 데이터의 sections[id].ver 로 고정됩니다.
 */
/* 편집기(브라우저)에서도 같은 코드를 쓰도록 공장 함수로 둠 — Editor.html 이 SL_RENDER_FACTORY_.toString() 으로 넣음 */
function SL_RENDER_FACTORY_() {
  var VERSION = '1.7.0';

  /* ─────────── 공통 도우미 ─────────── */
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function lines(s) { return esc(s).replace(/\n/g, '<br>'); }
  function has(v) { return v != null && String(v).trim() !== ''; }
  function arr(v) { return Array.isArray(v) ? v : []; }
  function attrUrl(u) {
    u = String(u || '').trim();
    return /^(https?:|tel:|sms:|mailto:|#|\/)/i.test(u) ? esc(u) : '';
  }
  /* 올린 사진: 'slimg:페이지번호' — 사진 자체는 블로그 정적 페이지(제목 sl-img)에 WebP 로 보관.
     IMG 에 데이터가 있으면 바로 넣고(첫 화면·명함 사진·편집기 미리보기), 없으면 홈페이지가 보일 때 불러옴(테마 [S16]) */
  var IMG = {};
  var IMG_PH = 'data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22/%3E';
  function setImages(map) { IMG = map || {}; }
  var IMG_BUDGET = 1e12;                                  // 한 페이지에 바로 넣는 사진 용량 (발행할 때만 제한)
  function imgRef(src) { var m = /^slimg:([\w-]+)$/.exec(String(src || '')); return m ? m[1] : ''; }
  function img(src, alt, w, h, cls) {
    if (!has(src)) return '';
    var ref = imgRef(src), data = ref && IMG[ref];
    if (data && data.length > IMG_BUDGET) data = '';       // 페이지가 너무 커지면 나머지는 나중에 불러오기
    else if (data) IMG_BUDGET -= data.length;
    var srcAttr = ref ? (data && /^data:image\/(webp|jpeg|png);base64,[A-Za-z0-9+\/=]+$/.test(data) ? 'src="' + data + '"' : 'src="' + IMG_PH + '" data-slimg="' + esc(ref) + '"') : 'src="' + attrUrl(src) + '"';
