  }

  /** 명함 사진·문구: 사장님이 넣은 것이 우선, 비어 있으면 홈페이지 내용을 그대로 씀
      프로필 사진  ← 명함 사진 → 대표(첫 번째 사람 소개) 사진 → (사진형 명함만) 첫 화면 사진
      커버 사진    ← 명함 커버 → 첫 화면 사진 → 갤러리 첫 장
      소개 글      ← 명함 소개 → 첫 화면 소개 문구 */
  var CARD_PHOTO_STYLES = { photo: 1, poster: 1, polaroid: 1 };
  function cardMedia(site, c) {
    var S = site.sections || {}, cd = c.cd;
    var hero = (S.hero || {}).data || {};
    var teamPhoto = (arr(((S.team || {}).data || {}).items).filter(function (x) { return has(x.photo); })[0] || {}).photo || '';
    var gal = (arr(((S.gallery || {}).data || {}).items).filter(function (x) { return has(x.src); })[0] || {}).src || '';
    var photo = cd.photo || teamPhoto || (CARD_PHOTO_STYLES[c.style] ? hero.image || gal || '' : '');
    return {
      photo: photo,
      photoFrom: cd.photo ? 'card' : (photo ? 'site' : ''),
      cover: cd.cover || hero.image || gal || '',
      intro: has(cd.intro) ? cd.intro : (hero.lead || '')
    };
  }

  function cardActs(site) {
    var b = site.biz;
    return arr(site.buttons).concat(has(b.email) ? [{ t: 'mail' }] : []).filter(function (x, i, a) {
      return a.map(function (y) { return y.t; }).indexOf(x.t) === i;
    }).map(function (x) {
      var href = x.t === 'mail' ? 'mailto:' + b.email : (BTN[x.t] ? BTN[x.t].href(x.v, site) : '');
      if (!has(href) || /^(tel:|sms:|mailto:)$/.test(href)) return '';
      var label = x.t === 'mail' ? '이메일' : (x.label || BTN[x.t].label);
      return '<li><a href="' + attrUrl(href) + '"' + (/^https?:/i.test(href) ? ' target="_blank" rel="noopener"' : '') + '>' +
        '<span class="sl-card-ico">' + (ICON[x.t] || ICON.link) + '</span><span>' + esc(label.replace(' 상담', '')) + '</span></a></li>';
    }).filter(has).slice(0, 6).join('');
  }

  /** 블록 하나 */
  function cardBlock(site, blk, c, ctx) {
    var b = site.biz, d = blk.data || {}, cd = c.cd;
    var wrap = function (html, title) {
      return html ? '<div class="sl-cblk sl-cblk-' + esc(blk.type) + '" data-cb="' + esc(blk.id || blk.type) + '">' + (has(title) ? '<p class="sl-cblk-h">' + esc(title) + '</p>' : '') + html + '</div>' : '';
    };
    switch (blk.type) {
      case 'intro':
        if (ctx.noIntro) return '';
        var intro = cardMedia(site, c).intro;
        return has(intro) ? wrap('<p class="sl-card-intro">' + lines(intro) + '</p>') : '';
      case 'actions':
        var acts = cardActs(site);
        return acts ? wrap('<ul class="sl-card-acts">' + acts + '</ul>') : '';
      case 'info':
        var info = '';
        if (has(b.phone)) info += '<div><dt>전화</dt><dd><a href="tel:' + esc(digits(b.phone)) + '">' + esc(b.phone) + '</a></dd></div>';
        if (has(b.email)) info += '<div><dt>이메일</dt><dd><a href="mailto:' + esc(b.email) + '">' + esc(b.email) + '</a></dd></div>';
        if (has(b.address)) info += '<div><dt>주소</dt><dd>' + esc(b.address) + '</dd></div>';
        if (b.hours && Object.keys(b.hours).length) info += '<div><dt>영업</dt><dd class="sl-status" data-hours="' + hoursAttr(site) + '">영업시간 안내</dd></div>';
        return info ? wrap('<dl class="sl-card-info">' + info + '</dl>') : '';
      case 'tools':
        var homeUrl = absUrl(site, '/'), cardUrl = absUrl(site, pageUrl(site, 'card'));
        return wrap('<div class="sl-card-tools">' +
          '<button type="button" class="sl-card-tool" data-sl="vcard">' + ICON.save + '<span>연락처 저장</span></button>' +
          '<button type="button" class="sl-card-tool" data-sl="share" data-url="' + esc(cardUrl) + '" data-title="' + esc(b.name + ' 모바일 명함') + '">' + ICON.share + '<span>명함 보내기</span></button>' +
          '<button type="button" class="sl-card-tool" data-sl="share" data-url="' + esc(homeUrl) + '" data-title="' + esc(b.name) + '">' + ICON.home + '<span>홈페이지 보내기</span></button>' +
          '</div>');
      case 'hours':
        if (!b.hours || !Object.keys(b.hours).length) return '';
        var dayIdx = { sun: 0, mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6 };
        return wrap('<table class="sl-card-hours sl-hours"><tbody>' + DAYS.map(function (x) {
          return '<tr data-day="' + dayIdx[x[0]] + '"><th scope="row">' + x[1] + '</th><td>' + esc(b.hours[x[0]] || '휴무') + '</td></tr>';
        }).join('') + '</tbody></table>' + (has(b.hoursNote) ? '<p class="sl-card-note">' + esc(b.hoursNote) + '</p>' : ''), d.title || '영업시간');
      case 'gallery':
        var items = arr(d.items).filter(function (x) { return has(x.src); });
        if (!items.length && blk.id === 'gallery') items = arr((((site.sections || {}).gallery || {}).data || {}).items).filter(function (x) { return has(x.src); });
        if (!items.length) return '';
        return wrap('<ul class="sl-card-gallery">' + items.slice(0, 9).map(function (x, i) {
          return '<li>' + img(x.src, x.alt || (b.name + ' 사진 ' + (i + 1)), 400, 400) + '</li>';
        }).join('') + '</ul>', d.title || '');
      case 'links':
        var ls = arr(d.items).filter(function (x) { return has(x.label) && attrUrl(x.url); });
        if (!ls.length) return '';
        return wrap('<ul class="sl-card-links">' + ls.map(function (x) {
          return '<li><a href="' + attrUrl(x.url) + '"' + (/^https?:/i.test(x.url) ? ' target="_blank" rel="noopener"' : '') + '>' + esc(x.label) + '</a></li>';
        }).join('') + '</ul>', d.title || '');
      case 'sns':
        var sn = arr(site.buttons).filter(function (x) { return /^(insta|blog|youtube|kakao)$/.test(x.t) && has(x.v); })
          .concat(arr(d.items).filter(function (x) { return BTN[x.t] && has(x.v); }));
        if (!sn.length) return '';
        return wrap('<ul class="sl-card-sns">' + sn.map(function (x) {
          return '<li><a href="' + attrUrl(x.v) + '" target="_blank" rel="noopener" aria-label="' + esc(BTN[x.t].label) + '">' + (ICON[x.t] || ICON.link) + '</a></li>';
        }).join('') + '</ul>');
      case 'video':
        var m = String(d.url || '').match(/(?:youtu\.be\/|v=|shorts\/|embed\/)([\w-]{11})/);
        if (!m) return '';
        return wrap('<a class="sl-video" href="https://www.youtube.com/watch?v=' + m[1] + '" target="_blank" rel="noopener">' +
          '<img src="https://i.ytimg.com/vi/' + m[1] + '/hqdefault.jpg" alt="' + esc(d.title || '영상') + '" width="480" height="360" loading="lazy" decoding="async">' +
          '<span class="sl-video-play" aria-hidden="true"></span><span class="sr-only">유튜브에서 영상 보기</span></a>', d.title || '');
      case 'map':
        if (!has(b.address)) return '';
        var q = encodeURIComponent(b.address);
        return wrap('<p class="sl-card-addr">' + esc(b.address) + '</p>' + (has(b.directions) ? '<p class="sl-card-note">' + lines(b.directions) + '</p>' : '') +
          '<div class="sl-card-mapbtns"><a href="https://map.naver.com/p/search/' + q + '" target="_blank" rel="noopener">네이버 지도</a>' +
          '<a href="https://map.kakao.com/?q=' + q + '" target="_blank" rel="noopener">카카오맵</a></div>', d.title || '오시는 길');
      case 'notice':
        return has(d.text) ? wrap('<p class="sl-card-notice">' + lines(d.text) + '</p>', d.title || '') : '';
      case 'text':
        return has(d.body) ? wrap('<div class="sl-card-text">' + String(d.body).split(/\n{2,}/).map(function (p) { return '<p>' + lines(p) + '</p>'; }).join('') + '</div>', d.title || '') : '';
      case 'homelinks':
        var ps = (site.pages || []).filter(function (p) { return p.id !== 'card' && !p.hidden && !p.nomenu; });
        if (!ps.length) return '';
        return wrap('<ul class="sl-card-site">' + ps.map(function (p) {
          return '<li><a href="' + attrUrl(pageUrl(site, p.id)) + '">' + esc(p.id === 'home' ? '홈페이지' : p.title) + '</a></li>';
        }).join('') + '</ul>', '홈페이지 둘러보기');
    }
    return '';
  }

  /** 명함 카드 전체. ctx: { tag: 상호에 쓸 태그, noIntro, only: [블록 종류 목록] } */
  function card(site, ctx) {
    ctx = ctx || {};
    var b = site.biz, c = cardData(site), cd = c.cd;
    var person = cd.person || b.owner || '';
    var role = cd.role || '';
    var media = cardMedia(site, c);
    var photo = media.photo;
    var cover = c.style === 'cover' ? media.cover : (cd.cover || '');
    var tag = ctx.tag || 'p';
    var personBig = c.primary === 'person' && has(person);
    /* 사진이 없을 때 쓰는 대체 문구: 사장님 지정 → 영문 상호 → '지역 업종' → 상호 */
    var alt = cd.placeholder || b.nameEn || [b.area, site.industryName].filter(has).join(' ') || b.name;
    var altEl = '<span class="sl-cph-word">' + esc(alt) + '</span>';
    var sub = [b.area, site.industryName].filter(has).join(' ');

    var bizEl = '<' + tag + ' class="' + (personBig ? 'sl-ccomp' : 'sl-card-name') + '">' + esc(b.name) + '</' + tag + '>';
    var personEl = personBig
      ? '<p class="sl-card-name">' + esc(person) + '</p>'
      : (has(person) ? '<p class="sl-card-person">' + esc(person) + '</p>' : '');
    var roleEl = has(role) ? '<p class="sl-crole">' + esc(role) + '</p>' : (has(sub) && !has(person) ? '<p class="sl-crole">' + esc(sub) + '</p>' : '');
    var logoEl = has(cd.logo) ? img(cd.logo, b.name + ' 로고', 160, 48, 'sl-clogo').replace(' loading="lazy"', '') : '';
    var photoEl = has(photo)
      ? '<figure class="sl-cphoto">' + img(photo, person || b.name, 800, 1000).replace('loading="lazy"', 'fetchpriority="high"') + '</figure>'
      : (CARD_PHOTO_STYLES[c.style] ? '<figure class="sl-cphoto is-empty" aria-hidden="true">' + altEl + '</figure>' : '');   // 얼굴 자리 모양은 사진 칸을 비움
    var coverEl = has(cover) ? '<figure class="sl-ccover">' + img(cover, b.name, 1200, 675) + '</figure>'
      : (c.style === 'cover' ? '<figure class="sl-ccover is-empty" aria-hidden="true">' + altEl + '</figure>' : '');
    /* 상호를 먼저 쓰는 모양(기업형·클래식)과 이름을 먼저 쓰는 모양 */
    var idHtml = personBig ? personEl + roleEl + bizEl : bizEl + personEl + roleEl;

    var prof = '<div class="sl-cprof">' + coverEl + photoEl + '<div class="sl-cid">' + logoEl + idHtml + '</div></div>';

    var blocks = c.blocks.filter(function (x) { return x && x.on !== false && CARD_BLOCKS[x.type]; });
    if (ctx.only) blocks = ctx.only.map(function (t) { return blocks.filter(function (x) { return x.type === t; })[0]; }).filter(Boolean);
    var body = blocks.map(function (x) { return cardBlock(site, x, c, ctx); }).join('');

    var vcard = esc(JSON.stringify({ fn: person || b.name, org: b.name, title: role, tel: b.phone || '', email: b.email || '', adr: b.address || '', url: absUrl(site, '/') }));
    return '<div class="sl-card sl-cs-' + c.style + ' sl-csh-' + c.shape + ' sl-cbt-' + c.btn + ' sl-cf-' + c.font + ' sl-canim-' + c.anim + ' sl-csf-' + c.surface + (has(photo) ? ' has-photo' : '') +
      '" data-vcard="' + vcard + '">' + prof + '<div class="sl-cbody">' + body + '</div></div>';
  }

  /* ─────────── 히어로 7종 ─────────── */
  var HERO_STYLES = {
    /* 간판: 상호를 아주 크게 — 사진 없이도 완성 (청소·수리·이사 등) */
    sign: function (x) {
      return '<div class="sl-wrap">' + x.place + x.title + x.lead + x.facts + x.btns + '</div>';
    },
    /* 전면 사진: 화면을 채운 사진 위에 상호 (미용·카페·인테리어) */
    cover: function (x) {
      return x.photo(1920, 1200) + '<div class="sl-hero-over"><div class="sl-wrap">' + x.place + x.title + x.lead + x.facts + x.btns + '</div></div>';
    },
    /* 반반: 왼쪽 글, 오른쪽 사진 (학원·병원·전문 서비스) */
    split: function (x) {
      return '<div class="sl-hero-text"><div class="sl-hero-inner">' + x.place + x.title + x.lead + x.facts + x.btns + '</div></div>' + x.photo(1200, 1400);
    },
    /* 액자: 가운데 정렬 글 아래 여백을 둔 사진 (스튜디오·공방·꽃집) */
    frame: function (x) {
      return '<div class="sl-wrap">' + x.place + x.title + x.lead + x.btns + '</div>' +
        '<div class="sl-wrap sl-hero-framewrap">' + x.photo(1600, 900) + x.facts + '</div>';
    },
    /* 차림표: 첫 화면에서 대표 메뉴와 가격 (식당·카페·미용) */
    menu: function (x) {
      var rows = x.menu.map(function (m) {
        return '<li><span class="sl-hm-name">' + esc(m.name) + '</span><span class="sl-leader" aria-hidden="true"></span><span class="sl-hm-price">' + esc(m.price) + '</span></li>';
      }).join('');
      return '<div class="sl-wrap sl-hero-menuwrap"><div class="sl-hero-text">' + x.place + x.title + x.lead + x.facts + x.btns + '</div>' +
        '<aside class="sl-hero-board" aria-label="대표 메뉴와 가격"><p class="sl-hero-board-title">대표 메뉴</p><ul>' + rows + '</ul></aside></div>';
    },
    /* 명함: 대표 얼굴 사진 + 이름·소개 (세무·법률·강사·1인 전문가) */
    profile: function (x) {
      return '<div class="sl-wrap sl-hero-profilewrap">' + x.photo(800, 1000) +
        '<div class="sl-hero-text">' + x.place + x.title + x.lead + x.facts + x.btns + '</div></div>';
    },
    /* 안내판: 지금 열었는지와 전화번호를 가장 크게 (병원·약국·관공서형) */
    notice: function (x) {
      var b = x.site.biz;
      return '<div class="sl-wrap">' + x.place + x.title + x.lead +
        '<div class="sl-hero-noticebox">' +
        (x.status ? '<ul class="sl-hero-bigstatus">' + x.status + '</ul>' : '') +
        (has(b.phone) ? '<a class="sl-hero-bigphone" href="tel:' + esc(digits(b.phone)) + '">' + esc(b.phone) + '</a>' : '') +
        (has(b.address) ? '<p class="sl-hero-addr">' + esc(b.address) + '</p>' : '') +
        '</div>' + x.btns + '</div>';
    },
    /* 매거진: 잡지 표지 — 위 머리띠, 아주 큰 제목, 사진과 옆 설명 (카페·베이커리·꽃집·공간) */
    magazine: function (x) {
      var b = x.site.biz;
      return '<div class="sl-wrap sl-wrap-plain">' +
        '<div class="sl-mag-bar"><span>' + esc([b.area, x.site.industryName].filter(has).join(' · ')) + '</span><span>' + esc((b.nameEn || b.name) + ' JOURNAL') + '</span></div>' +
        x.title +
        '<div class="sl-mag-grid' + (has(x.d.image) ? '' : ' is-text') + '">' + (has(x.d.image) ? x.photo(1600, 1000) : '') +
        '<div class="sl-mag-side">' + x.place + x.lead + x.facts + x.btns + '</div></div></div>';
    },
    /* 포트폴리오: 이름을 크게, 오른쪽에 작업 사진 3장 (사진·디자인·공방·1인 작가) */
    portfolio: function (x) {
      var works = x.works.slice(0, 3).map(function (src, i) {
        return '<li>' + img(src, x.site.biz.name + ' 작업 ' + (i + 1), 900, 1100).replace(i === 0 ? 'loading="lazy"' : '__', 'fetchpriority="high"') + '</li>';
      }).join('');
      return '<div class="sl-wrap sl-wrap-plain sl-hero-portwrap"><div class="sl-hero-text">' + x.place + x.title + x.lead +
        (x.status ? '<ul class="sl-hero-chip">' + x.status + '</ul>' : '') + x.btns + '</div>' +
        '<ul class="sl-hero-works sl-works-' + Math.min(x.works.length, 3) + '">' + works + '</ul></div>';
    },
    /* 명함: 첫 화면이 모바일 명함 — 저장·보내기까지 (1인 전문가·설계사·중개·강사) */
    card: function (x) {
      return '<div class="sl-wrap sl-wrap-plain sl-hero-cardwrap">' +
        '<div class="sl-hero-text">' + x.place + (has(x.d.lead) ? '<p class="sl-hero-statement">' + lines(x.d.lead) + '</p>' : '') + x.btns + '</div>' +
        card(x.site, { tag: x.tag, noIntro: has(x.d.lead), only: ['actions', 'info', 'tools'] }) + '</div>';
    }
  };

  /* ─────────── 모듈 (섹션 종류) ─────────── */
  var MODS = {
    /* 히어로 7종 — 업종별 기본값이 있고 사장님이 바꿀 수 있음.
       사진이 필요한 모양에 사진이 없으면 '간판'으로, 가격이 없는 '차림표'도 '간판'으로 자동 대체 */
    hero: { ver: '1.1.0', name: '첫 화면', styles: ['sign', 'cover', 'split', 'frame', 'menu', 'profile', 'notice', 'magazine', 'portfolio', 'card'], render: function (d, site, ctx) {
      var b = site.biz;
      var t = ctx.isHome ? 'h1' : 'p';
      var style = HERO_STYLES[site.style.hero] ? site.style.hero : 'sign';
      var menuItems = arr(((site.sections || {}).services || {}).data && site.sections.services.data.items).filter(function (x) { return has(x.name) && has(x.price); });
      if ((style === 'cover' || style === 'split' || style === 'frame' || style === 'profile') && !has(d.image)) style = 'sign';
      if (style === 'menu' && (!menuItems.length || (site.sections.services.data || {}).priceMode === 'ask')) style = 'sign';
      var works = [d.image].concat(arr((((site.sections || {}).gallery || {}).data || {}).items).map(function (x) { return x.src; })).filter(has);
      if (style === 'portfolio' && !works.length) style = 'sign';

      var status = (b.hours && Object.keys(b.hours).length) ? '<li class="sl-status" data-hours="' + hoursAttr(site) + '">영업시간 안내</li>' : '';
      var facts = status + (has(b.address) ? '<li>' + esc(b.address) + '</li>' : '') +
        (has(b.phone) ? '<li><a href="tel:' + esc(digits(b.phone)) + '">' + esc(b.phone) + '</a></li>' : '');
      var place = has(d.eyebrow) ? '<p class="sl-hero-place">' + esc(d.eyebrow) + '</p>' : '';
      var title = '<' + t + ' class="sl-hero-title">' + esc(d.title || b.name) + '</' + t + '>';
      var lead = has(d.lead) ? '<p class="sl-hero-lead">' + lines(d.lead) + '</p>' : '';
      var factList = facts ? '<ul class="sl-hero-facts">' + facts + '</ul>' : '';
      var btns = '<div class="sl-hero-btns">' + buttons(site, arr(site.buttons).slice(0, 2)) + '</div>';
      /* 첫 화면 사진은 바로 내려받음 (LCP) */
      var photo = function (w, h) { return '<figure class="sl-hero-photo">' + img(d.image, b.name, w, h).replace('loading="lazy"', 'fetchpriority="high"') + '</figure>'; };
      return '<div class="sl-hero sl-hero-' + style + '">' + HERO_STYLES[style]({
        place: place, title: title, lead: lead, facts: factList, btns: btns, photo: photo, status: status,
        site: site, d: d, menu: menuItems.slice(0, 5), works: works, tag: t
      }) + '</div>';
    }},

    trust: { ver: '1.0.0', name: '신뢰 정보', render: function (d) {
      var items = arr(d.items).filter(function (x) { return has(x.value); });
      if (!items.length) return '';
      return '<div class="sl-wrap sl-wrap-plain"><dl class="sl-trust">' + items.map(function (x) {
        return '<div' + hasImg(x) + '><dt>' + esc(x.label) + '</dt><dd>' + esc(x.value) + '</dd>' +
          (has(x.image) ? '<dd class="sl-trust-ph">' + itemImg(x.image, x.label || x.value) + '</dd>' : '') + '</div>';
      }).join('') + '</dl></div>';
    }},

    about: { ver: '1.0.0', name: '소개', variants: ['split', 'center', 'photo'], render: function (d, site) {
      return '<div class="sl-wrap">' + head(d, site.biz.name + ' 소개') + body(
        (has(d.body) ? '<div class="sl-text">' + String(d.body).split(/\n{2,}/).map(function (p) { return '<p>' + lines(p) + '</p>'; }).join('') + '</div>' : '') +
        img(d.image, site.biz.name, 1200, 800, 'sl-img') +
