    cta: { ver: '1.1.0', name: '마무리 연락', variants: ['phone', 'banner'], render: function (d, site) {
      /* 마무리: 이 업종의 실제 행동(전화)을 가장 크게 */
      var phone = site.biz.phone;
      var rest = arr(site.buttons).filter(function (b) { return !(has(phone) && b.t === 'call'); }).slice(0, 3);
      /* 제목 묶음(sl-head) + 행동 묶음(sl-cta-act): 다른 섹션과 같은 간격 규칙을 받음 */
      var acts = (has(phone) ? '<a class="sl-cta-phone" href="tel:' + esc(digits(phone)) + '">' + esc(phone) + '</a>' : '') +
        (rest.length ? '<div class="sl-hero-btns">' + buttons(site, rest) + '</div>' : '');
