/** 판매자에게 보내기 (실패하면 null) */
function scenePost_(body) {
  var url = sceneUrl_(); if (!url) return null;
  try {
    var r = UrlFetchApp.fetch(url, { method: 'post', contentType: 'text/plain', payload: JSON.stringify(body), muteHttpExceptions: true, followRedirects: true });
    return safeJson_(r.getContentText());
  } catch (e) { return null; }
}

/** 이 지역에서 다른 가게가 이미 쓰는 씬 (편집기 잠금 표시용 · 10분 보관) */
