  if (!region || !ind || !sceneUrl_()) return { ok: true, region: region, taken: [], registry: false };
  var key = 'SC_TAKEN_' + Utilities.base64EncodeWebSafe(region + '|' + ind).slice(0, 200), cache = CacheService.getScriptCache(), hit = cache.get(key);
  if (hit) return JSON.parse(hit);
  var res = scenePost_({ a: 'sceneTaken', blogId: PROPS.getProperty('BLOG_ID') || '', region: region, industry: ind });
  var out = { ok: true, region: region, taken: res && res.ok ? (res.taken || []) : [], registry: !!(res && res.ok) };
