  var own = SL_RENDER.sceneValid(site, F.sceneOk) && !/^brand-/.test(F.sceneOk) && F.sceneRegion === region;
  /* 이미 이 지역에 등록된 업종 씬: 직접 고른 씬이 없거나 같으면 그대로 (자동 씬이 저장할 때마다 바뀌지 않게) */
  if (own && (!pick || pick === F.sceneOk)) return F.sceneOk;
  if (url === null) { if (!SL_RENDER.sceneValid(site, F.sceneOk)) F.sceneOk = 'brand-1'; return F.sceneOk; }   // 판매자 정보를 못 받음 → 지난 씬 유지
  if (!url || !region) { F.sceneOk = order[0] || ''; delete F.sceneRegion; return F.sceneOk; }                  // 개발·시험(등록부 없음) 또는 주소 없음
  for (var i = 0; i < order.length; i++) {
