    var sid = ScriptApp.getScriptId();
    var v = scriptApi_('post', '/projects/' + sid + '/versions', { description: '사이트루미 ' + CORE_VER + ' 설치' });
    d = scriptApi_('post', '/projects/' + sid + '/deployments', { versionNumber: v.versionNumber, manifestFileName: 'appsscript', description: '사이트루미 편집기' });
    if (d && d.deploymentId) PROPS.setProperty('DEPLOY_ID', d.deploymentId);
  }
  var url = urlOf(d);
  if (!WEBAPP_RE_.test(url)) throw new Error('배포는 됐지만 웹앱 주소를 읽지 못했습니다. [배포 › 배포 관리]에서 주소를 확인하세요.');
  PROPS.setProperty('WEBAPP_URL', url);
  return url;
}

/** 이 구글 계정의 블로그 목록 */
function listBlogs_() {
  var res = UrlFetchApp.fetch('https://www.googleapis.com/blogger/v3/users/self/blogs?fields=items(id,name,url)',
    { headers: { Authorization: 'Bearer ' + ScriptApp.getOAuthToken() }, muteHttpExceptions: true });
  if (res.getResponseCode() !== 200) throw new Error('HTTP ' + res.getResponseCode() + ' ' + res.getContentText().slice(0, 300));
  return ((safeJson_(res.getContentText()) || {}).items || []).map(function (b) {
    return { id: b.id, name: b.name, url: String(b.url || '').replace(/^http:/, 'https:').replace(/\/?$/, '/') };
  });
}

/** 설치 코드 확인 (틀린 횟수 제한) */
function setupGate_(req) {
  if (PROPS.getProperty('ADMIN_HASH')) return { ok: false, code: 'DONE', error: '이미 설치가 끝났습니다. 로그인해 주세요.' };
  var want = PROPS.getProperty('SETUP_CODE');
  if (!want) return { ok: false, code: 'NOCODE', error: '앱스 스크립트에서 「설치하기」를 먼저 실행해 설치 코드를 받으세요.' };
  var cache = CacheService.getScriptCache(), n = Number(cache.get('SETUP_FAIL') || 0);
  if (n >= SETUP_TRY_MAX) return { ok: false, code: 'LOCKED', error: '설치 코드를 너무 많이 틀렸습니다. ' + SETUP_LOCK_MIN + '분 뒤 다시 시도하세요.' };
  if (String(req.setupCode || '').replace(/\D/g, '') !== want) {
    cache.put('SETUP_FAIL', String(n + 1), SETUP_LOCK_MIN * 60);
    return { ok: false, code: 'CODE', error: '설치 코드가 맞지 않습니다. 실행 로그의 6자리 숫자를 확인하세요.' };
  }
  return null;
}

/** 설치 화면 1: 코드 확인 → 블로그 목록 · 이 계정 메일 */
function setupInfo_(req) {
  var g = setupGate_(req); if (g) return g;
  var blogs = listBlogs_();
  rememberWebApp_();
  return { ok: true, blogs: blogs, email: Session.getEffectiveUser().getEmail(), webAppUrl: webAppUrl_() };
}

/** 설치 화면 2: 고른 블로그 자동 점검 — 테마 · 로봇 태그 · 피드 · 웹앱 */
function setupCheck_(req) {
  var g = setupGate_(req); if (g) return g;
  var blog = listBlogs_().filter(function (b) { return b.id === String(req.blogId || ''); })[0];
  if (!blog) return { ok: false, error: '이 구글 계정의 사이트가 아닙니다.' };
  return { ok: true, checks: siteChecks_(blog.url) };
}

/** 블로그 상태 점검 (설치 화면 · 대시보드 공용) */
function siteChecks_(url) {
  var out = [], html = '';
  try { html = fetchText_(url + '?sl-check=' + Date.now()); } catch (e) { html = ''; }
  var theme = /__slEarly/.test(html) ? 'ok' : /field-sizing|sl-sitefoot/.test(html) ? 'old' : 'none';
  out.push({ k: 'theme', ok: theme === 'ok', must: true, label: '사이트루미 테마',
    help: theme === 'ok' ? '' : theme === 'old' ? '예전 버전 테마입니다. 새 테마 파일을 테마 › HTML 편집에 통째로 붙여넣고 저장하세요.' :
      '블로그 › 테마 › 맞춤설정 ▼ › HTML 편집 → 내용을 모두 지우고 사이트루미 테마 파일을 붙여넣은 뒤 저장하세요.' });
  var robots = (html.match(/<meta[^>]+name=["']robots["'][^>]*>/gi) || []).length;
  out.push({ k: 'robots', ok: robots <= 1, must: false, label: '로봇 태그 1개',
    help: robots <= 1 ? '' : '블로그 › 설정 › 크롤러 및 색인 생성 › 「맞춤 로봇 헤더 태그 사용」을 끄세요.' });
  var feed = 0;
  try { feed = UrlFetchApp.fetch(url + 'feeds/pages/summary?alt=json&max-results=1', { muteHttpExceptions: true }).getResponseCode(); } catch (e) {}
  out.push({ k: 'feed', ok: feed === 200, must: true, label: '사이트 피드 허용',
    help: feed === 200 ? '' : '블로그 › 설정 › 사이트 피드 › 「블로그 피드 허용」을 「전부」로 바꾸세요. (홈 화면이 피드로 열립니다)' });
  /* 블로그 기본 설정: 검색엔진 표시 · HTTPS 리디렉션 (설치 안내 1단계) — 고치지 않아도 설치는 됨 */
  var hidden = /<meta[^>]+name=["']robots["'][^>]+noindex/i.test(html) || /<meta[^>]+content=["'][^"']*noindex[^>]+name=["']robots["']/i.test(html);
  try { if (!hidden) hidden = /User-agent:\s*\*\s*\n\s*Disallow:\s*\/\s*(\n|$)/i.test(fetchText_(url + 'robots.txt')); } catch (e) {}
  out.push({ k: 'search', ok: !hidden, must: false, label: '검색엔진에 표시',
    help: hidden ? '블로그 › 설정 › 개인정보 보호 › 「검색엔진에 표시됨」을 켜세요. 꺼져 있으면 네이버·구글 검색에 나오지 않습니다.' : '' });
  var https = true;
  try {
    var hr = UrlFetchApp.fetch(url.replace(/^https:/, 'http:'), { followRedirects: false, muteHttpExceptions: true });
    var loc = String((hr.getHeaders() || {}).Location || (hr.getHeaders() || {}).location || '');
    https = hr.getResponseCode() >= 300 && hr.getResponseCode() < 400 && /^https:/i.test(loc);
  } catch (e) {}
  out.push({ k: 'https', ok: https, must: false, label: 'HTTPS 리디렉션',
    help: https ? '' : '블로그 › 설정 › 게시 › 「HTTPS 리디렉션」을 켜세요. 주소창에 「주의 요함」이 뜨지 않고 검색에도 유리합니다.' });
  var web = webAppUrl_();
  out.push({ k: 'webapp', ok: !!web, must: false, label: '웹앱 주소 확인',
    help: web ? '' : '자동으로 찾지 못했습니다. 지금 이 화면을 연 주소(…/exec)를 아래 칸에 붙여넣으세요.' });
  return out;
}

/** 설치 화면 3: 관리자 만들기 + 블로그 연결 저장 + 밤 12시 자동 기록 → 바로 로그인 */
function setup_(req) {
  var g = setupGate_(req); if (g) return g;
  var blog = listBlogs_().filter(function (b) { return b.id === String(req.blogId || ''); })[0];
  if (!blog) return { ok: false, error: '사이트를 골라 주세요.' };
  var id = String(req.id || '').trim().toLowerCase(), pw = String(req.pw || ''), email = String(req.email || '').trim();
  if (!/^[a-z0-9_]{4,20}$/.test(id)) return { ok: false, field: 'id', error: '아이디는 영문 소문자·숫자·_ 4~20자로 정해 주세요.' };
  if (pw.length < 8) return { ok: false, field: 'pw', error: '비밀번호는 8자 이상으로 정해 주세요.' };
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) return { ok: false, field: 'email', error: '아이디·비밀번호를 잊었을 때 받을 이메일을 넣어 주세요.' };
  var checks = siteChecks_(blog.url).filter(function (c) { return c.must && !c.ok; });
  if (checks.length) return { ok: false, code: 'CHECK', error: checks[0].label + ' — ' + checks[0].help };
  var web = String(req.webAppUrl || '').trim();
  if (web && !WEBAPP_RE_.test(web)) return { ok: false, field: 'web', error: '웹앱 주소는 https://script.google.com/macros/s/…/exec 모양이어야 합니다.' };

  var lock = LockService.getScriptLock(); lock.waitLock(20000);
  try {
    if (PROPS.getProperty('ADMIN_HASH')) return { ok: false, code: 'DONE', error: '이미 설치가 끝났습니다. 로그인해 주세요.' };
    PROPS.setProperties({ BLOG_ID: blog.id, BLOG_URL: blog.url, BLOG_NAME: blog.name, ADMIN_ID: id, ADMIN_EMAIL: email });
    if (web) PROPS.setProperty('WEBAPP_URL', web); else rememberWebApp_();
    setPassword_(pw);
    if (!PROPS.getProperty('TOKEN_SECRET')) PROPS.setProperty('TOKEN_SECRET', newSecret_());
    PROPS.deleteProperty('SETUP_CODE');
    CacheService.getScriptCache().remove('SETUP_FAIL');
  } finally { lock.releaseLock(); }
  try { installSnapTrigger_(); slSnapPageviews(); } catch (e) {}      // 블로거 기준 날짜별 방문 기록 (실패해도 설치는 계속)
  try { installUpdateTrigger_(); } catch (e) {}                         // 새벽 자동 업그레이드 확인
  try { updateReport_(CORE_VER, 'installed'); } catch (e) {}            // 판매자 사이트 목록에 알림 (선택)
  var exp = Date.now() + TOKEN_HOURS * 3600e3;
  return { ok: true, token: makeToken_({ u: id, v: tokenVer_(), exp: exp }, PROPS.getProperty('TOKEN_SECRET')), exp: exp,
           blogUrl: blog.url, blogName: blog.name, webAppUrl: webAppUrl_() };
}

/**
 * 사이트루미 저장소 v1.0 — 사이트 데이터와 페이지를 블로거 '정적 페이지'에 씁니다.
 *
 *   데이터 페이지  (제목 sl-data)  : <div class="sl-store" data-kind="data">~~SLB~~data:rev:base64(JSON)~~SLE~~</div>
 *   홈 페이지      (제목 sl-home)  : 홈 HTML — 테마의 홈 로더가 읽어 #hp-root 에 넣음 (검색 색인 제외)
 *   하위 페이지    (/p/slug.html) : 페이지 HTML 그대로 — 자바스크립트 없이 검색·AI 가 읽음
 *
 * 스크립트 속성: DATA_PAGE, HOME_PAGE, PG_<페이지id> = 블로거 페이지 id, PH_<페이지id> = 마지막 HTML 해시
 */
var SLB = '~~SLB~~', SLE = '~~SLE~~';

function slStoreWrap_(kind, payload) {
  return '<div class="sl-store" data-kind="' + kind + '" style="display:none">' + SLB + payload + SLE + '</div>';
}
function slStoreUnwrap_(html) {
  var s = String(html || ''), a = s.indexOf(SLB), z = s.indexOf(SLE);
  return a < 0 || z < a ? null : s.slice(a + SLB.length, z).replace(/\s+/g, '');
}

/** 데이터 읽기 (없으면 null) */
function slLoad_() {
  var id = PROPS.getProperty('DATA_PAGE');
  if (!id) return null;
  var page;
  try { page = api_('get', '/pages/' + id, null, { view: 'ADMIN', fields: 'content' }); }
  catch (e) { if (/_404/.test(e.message)) { PROPS.deleteProperty('DATA_PAGE'); return null; } throw e; }   // 저장 페이지를 블로거에서 지운 경우
  var p = (slStoreUnwrap_(page.content) || '').split(':');
  if (p[0] !== 'data' || !p[2]) return null;
  return JSON.parse(Utilities.newBlob(Utilities.base64Decode(p[2])).getDataAsString('UTF-8'));
}

/**
 * 저장 + 바뀐 페이지만 다시 발행
 * baseRev 가 현재 rev 와 다르면 CONFLICT (다른 기기에서 먼저 저장함)
 */
function slSave_(site, baseRev) {
  var lock = LockService.getScriptLock(); lock.waitLock(20000);
  try {
    var cur = slLoad_();
    var curRev = cur ? Number(cur.rev || 0) : 0;
    if (cur && baseRev != null && Number(baseRev) !== curRev) return { ok: false, code: 'CONFLICT', error: '다른 기기에서 먼저 저장했습니다. 새로고침 후 다시 저장하세요.', rev: curRev };
    site.rev = curRev + 1;
    site.savedAt = new Date().toISOString();
    site.baseUrl = blogUrl_();
    site.gasUrl = webAppUrl_();                  // 홈페이지 상담 신청·방문 기록이 보낼 주소
    slEnsureCore(site);                          // 명함·이용약관·개인정보처리방침 페이지가 없으면 추가
    slTidyPhones_(site);                         // 전화번호 하이픈 맞춤
    site.plan = slPlan_();                       // 상품 등급 (유료 기능: 검색 최적화 등) — 편집기에서 보낸 값은 쓰지 않음
    try { sceneResolve_(site); } catch (e) {}    // 시그니처 씬: 같은 지역 겹침 확인 뒤 쓸 씬을 정함 (표준 이상)
    customKeep_(site, cur);                      // 맞춤 코드는 판매자 서명본만 (편집기 값 무시)

    var published = null;
    var missing = SL_RENDER.legalMissing(site);  // 민감업종 필수 표시가 비어 있으면 저장만 하고 공개 화면은 바꾸지 않음
    SL_RENDER.setImages(slEagerImages_(site));   // 첫 화면·명함 사진은 페이지에 바로 넣음
    try { if (!missing.length) published = slPublish_(site); }   // 페이지 먼저 → 페이지 주소를 데이터에 기록
    catch (e) {
      if (/BLOGGER_429/.test(e.message)) return { ok: false, code: 'RATE', error: '저장이 잠시 몰렸어요 — 잠시 뒤 다시 저장하면 이어서 진행합니다.' };
      if (/PAGE_TOO_BIG/.test(e.message)) return { ok: false, code: 'BIG', error: '「' + e.message.replace('PAGE_TOO_BIG ', '') + '」 페이지가 너무 커요. 사진 수를 줄이거나 사진 주소로 넣어 주세요.' };
      throw e;
    }
    finally { SL_RENDER.setImages({}); }
    var payload = 'data:' + site.rev + ':' + Utilities.base64Encode(JSON.stringify(site), Utilities.Charset.UTF_8);
    var id = PROPS.getProperty('DATA_PAGE');
    var body = { title: 'sl-data', content: slStoreWrap_('data', payload) };
    var page = id ? tryPatch_('/pages/' + id, body) : null;
    if (!page) { page = api_('post', '/pages/', body, { isDraft: 'false' }); PROPS.setProperty('DATA_PAGE', page.id); }
    try { bookSaveCfg_(site); } catch (e) {}       // 예약 설정 따로 보관 (손님 요청이 빠르게)
    return { ok: true, rev: site.rev, pages: published || {}, dataPage: page.id,
             held: missing.length ? missing.map(function (m) { return m.label; }) : undefined };
  } finally { lock.releaseLock(); }
}

/** 페이지 발행: 내용이 바뀐 페이지만 쓰고, 사이트에서 빠진 페이지는 임시글로 되돌림(주소 보존) */
function slPublish_(site) {
  var out = {}, keep = {};
  /* 홈은 하위 페이지 주소가 정해진 뒤 마지막에 발행 */
  var order = (site.pages || []).filter(function (p) { return p.id !== 'home'; })
    .concat((site.pages || []).filter(function (p) { return p.id === 'home'; }));
  order.forEach(function (p) {
    keep[p.id] = true;
    var isHome = p.id === 'home';
    var key = 'PG_' + p.id;
    var pid = PROPS.getProperty(key);

    if (p.hidden) {                                   // 숨긴 페이지 → 임시글 (나중에 다시 켜면 같은 주소로 복귀)
      if (pid && !PROPS.getProperty('PD_' + p.id)) { try { api_('post', '/pages/' + pid + '/revert'); } catch (e) {} PROPS.deleteProperty('PH_' + p.id); PROPS.setProperty('PD_' + p.id, '1'); }
      return;
    }
    var wasDraft = !!PROPS.getProperty('PD_' + p.id);
    var html = SL_RENDER.renderPage(site, p.id);
    if (isHome) html = slStoreWrap_('home', 'home:' + site.rev + ':' + Utilities.base64Encode(html, Utilities.Charset.UTF_8));
    var hash = Utilities.base64Encode(Utilities.computeDigest(Utilities.DigestAlgorithm.MD5, html + '|' + p.title, Utilities.Charset.UTF_8));
    var title = isHome ? 'sl-home' : p.title;

    if (html.length > 950000) throw new Error('PAGE_TOO_BIG ' + p.title);   // 블로거 페이지 1MB 제한
    if (pid && !wasDraft && PROPS.getProperty('PH_' + p.id) === hash) { out[p.id] = p.url || ''; return; }   // 바뀐 것 없음

    var page = null;
    if (pid) {
      page = tryPatch_('/pages/' + pid, { title: title, content: html });
      if (page && (wasDraft || (page.status && page.status !== 'LIVE'))) { try { api_('post', '/pages/' + pid + '/publish'); } catch (e) {} }
    }
    if (!page) {
      /* 새 페이지: 영문 주소로 만든 뒤 한글 제목으로 바꿈 → 주소는 /p/slug.html 로 고정 */
      var slug = isHome ? 'sl-home' : (p.slug || p.id);
      page = api_('post', '/pages/', { title: slug, content: html }, { isDraft: 'false' });
      PROPS.setProperty(key, page.id);               // 만들자마자 기억 → 다음 단계에서 멈춰도 중복 생성 없음
      if (title !== slug) page = api_('patch', '/pages/' + page.id, { title: title });
    }
    PROPS.setProperty('PH_' + p.id, hash); PROPS.deleteProperty('PD_' + p.id);
    p.url = page.url ? page.url.replace(/^https?:\/\/[^/]+/, '') : p.url;
    out[p.id] = page.url || '';
  });
  /* 사이트에서 아예 지운 페이지 → 임시글로 */
  Object.keys(PROPS.getProperties()).forEach(function (k) {
    if (/^PG_/.test(k) && !keep[k.slice(3)] && !PROPS.getProperty('PD_' + k.slice(3))) {   // 한 번만
      try { api_('post', '/pages/' + PROPS.getProperty(k) + '/revert'); } catch (e) {}
      PROPS.deleteProperty('PH_' + k.slice(3)); PROPS.setProperty('PD_' + k.slice(3), '1');
    }
  });
  return out;
}

/** 저장 전에 전화번호 모양을 맞춤 (010-1234-5678 · 02-123-4567 · 1588-1234 …) */
function slTidyPhones_(site) {
  var f = SL_RENDER.fmtTel, b = site.biz || {};
  if (b.phone) b.phone = f(b.phone);
  var pv = site.sections && site.sections.privacy && site.sections.privacy.data;
  if (pv && pv.officerPhone) pv.officerPhone = f(pv.officerPhone);
  (site.buttons || []).forEach(function (x) { if ((x.t === 'call' || x.t === 'sms') && x.v) x.v = f(x.v); });
  return site;
}

/**
 * 사이트루미 자동 업그레이드 (구매자 계정에서 스스로 새 버전으로 바꿈)
 * ------------------------------------------------------------------------
 *  판매자 Firebase Hosting 의 manifest.json 을 하루 한 번 읽고, 이 사이트가 받을 버전이 더 새로우면
 *   ① 엔진 묶음(bundle-x.y.z.json)을 받아 지문(SHA-256)을 확인하고
 *   ② Apps Script API 로 이 프로젝트의 파일을 통째로 바꾼 뒤(projects.updateContent)
 *   ③ 새 버전을 만들고(versions.create) 웹앱 배포를 그 버전으로 옮김(deployments.update) → 편집기 주소 그대로
 *
 *  규칙
 *   - 같은 큰 번호(4.x → 4.y)는 자동, 큰 번호가 바뀌는 업그레이드(4.x → 5.0)는 편집기에서 「올리기」를 눌러야 함
 *   - manifest 의 pins 에 이 블로그가 있으면 그 버전에 고정 (판매자가 사이트별로 묶어 두기·되돌리기)
 *   - rollout: 새 버전을 사이트 일부(퍼센트)에만 먼저 — 블로그 번호로 나눠 늘 같은 사이트가 먼저 받음
 *   - 이름이 my_ 로 시작하는 파일은 업데이트가 건드리지 않음 (구매자·판매자가 따로 넣은 코드)
 *   - 실패하면 아무것도 바꾸지 않고 기록만 남김. 문제가 생기면 편집기 「이전 버전으로」로 바로 되돌림
 *
 *  필요한 것 (설치 때 한 번): 이 프로젝트에 연결된 GCP 프로젝트에서 「Apps Script API」 사용 +
 *   script.google.com/home/usersettings 에서 「Google Apps Script API」 켜기
 */

var UPDATE_DEFAULT_URL = 'https://raw.githubusercontent.com/hoonk740-dotcom/sitelumi-design/main/engine/manifest.json';   // 판매자 GitHub 저장소 engine/ (원본에서 바로 · 5분 캐시) — 안 되면 jsDelivr·GitHub Pages
var UPDATE_KEEP_RE = /^my[_-]/i;
var UPDATE_HOUR = 4;                       // 새벽 4시쯤 자동 확인

function updateUrl_() { return PROPS.getProperty('UPDATE_URL') || UPDATE_DEFAULT_URL; }
/* 예비 주소: jsDelivr 가 안 되면 같은 저장소의 GitHub Pages 에서 받음 (내용은 SHA-256 으로 확인하므로 어디서 받아도 안전) */
var UPDATE_MIRROR_ = ['https://raw.githubusercontent.com/hoonk740-dotcom/sitelumi-design/main/', 'https://cdn.jsdelivr.net/gh/hoonk740-dotcom/sitelumi-design@main/', 'https://hoonk740-dotcom.github.io/sitelumi-design/'];
function updateGet_(url) {
  var urls = [url];
  UPDATE_MIRROR_.forEach(function (pre) {                 // 같은 파일의 다른 주소들 (원본 → jsDelivr → GitHub Pages)
    if (url.indexOf(pre) !== 0) return;
    var rest = url.slice(pre.length);
    UPDATE_MIRROR_.forEach(function (alt) { if (alt !== pre) urls.push(alt + rest); });
  });
  var last = null;
  for (var i = 0; i < urls.length; i++) {
    try { last = UrlFetchApp.fetch(urls[i], { muteHttpExceptions: true, followRedirects: true }); if (last.getResponseCode() === 200) return last; } catch (e) { last = null; }
  }
  return last || { getResponseCode: function () { return 0; }, getContentText: function () { return ''; } };
}

function verParts_(v) { var m = String(v || '').match(/^(\d+)\.(\d+)\.(\d+)/); return m ? [Number(m[1]), Number(m[2]), Number(m[3])] : [0, 0, 0]; }
function verCmp_(a, b) { a = verParts_(a); b = verParts_(b); for (var i = 0; i < 3; i++) if (a[i] !== b[i]) return a[i] < b[i] ? -1 : 1; return 0; }

/** manifest.json (1시간 보관) */
function updateManifest_(fresh) {
  var cache = CacheService.getScriptCache(), hit = !fresh && cache.get('UPD_MANIFEST');
  if (hit) return JSON.parse(hit);
  var res = updateGet_(updateUrl_());
  if (res.getResponseCode() !== 200) throw new Error('업데이트 정보를 받지 못했습니다 (HTTP ' + res.getResponseCode() + ')');
  var m = safeJson_(res.getContentText());
  if (!m || m.app !== 'sitelumi' || !m.stable || !m.bundles) throw new Error('업데이트 정보 형식이 올바르지 않습니다.');
  try { cache.put('UPD_MANIFEST', JSON.stringify(m), 3600); } catch (e) {}
  return m;
}

/** 이 사이트가 받을 버전: 고정(pins) > 먼저 받기(rollout) > 안정(stable) */
function updateTarget_(m) {
  var id = String(PROPS.getProperty('BLOG_ID') || ''), host = String(blogUrl_() || '').replace(/^https?:\/\//, '').replace(/\/.*$/, '');
  var pins = m.pins || {};
  if (pins[id]) return { ver: pins[id], why: 'pin' };
  if (host && pins[host]) return { ver: pins[host], why: 'pin' };
  var r = m.rollout;
  if (r && r.version && Number(r.percent) > 0 && updateBucket_(id || host) < Number(r.percent)) return { ver: r.version, why: 'rollout' };
  return { ver: m.stable, why: 'stable' };
}
function updateBucket_(key) {
  var d = Utilities.computeDigest(Utilities.DigestAlgorithm.MD5, String(key || 'x'));
  return ((d[0] & 255) * 256 + (d[1] & 255)) % 100;
}

/** 편집기 「설정」에 보여 줄 업데이트 상태 */
function updateInfo_(fresh) {
  var out = { ok: true, current: CORE_VER, url: updateUrl_(), last: safeJson_(PROPS.getProperty('UPDATE_LAST') || 'null'),
              err: PROPS.getProperty('UPDATE_ERR') || '', canRollback: !!PROPS.getProperty('UPDATE_PREV_VERSION'), majorOk: PROPS.getProperty('UPDATE_MAJOR_OK') === '1' };
  try {
    var m = updateManifest_(fresh), t = updateTarget_(m);
    out.target = t.ver; out.why = t.why; out.notes = (m.notes || {})[t.ver] || '';
    out.newer = verCmp_(t.ver, CORE_VER) > 0;
    out.major = out.newer && verParts_(t.ver)[0] > verParts_(CORE_VER)[0];
    out.blocked = (m.blocked || []).indexOf(t.ver) >= 0;
  } catch (e) { out.checkErr = e.message; }
  return out;
}

/** 업데이트 실행. opts: { optIn: 큰 번호 업그레이드 허락, to: 특정 버전, force: 같은 버전 다시 깔기 } */
function updateApply_(opts) {
  opts = opts || {};
  var lock = LockService.getScriptLock();
  if (!lock.tryLock(30000)) return { ok: false, error: '다른 업데이트가 진행 중입니다. 잠시 뒤 다시 시도해 주세요.' };
  try {
    var m = updateManifest_(true), t = opts.to ? { ver: opts.to, why: 'manual' } : updateTarget_(m);
    var cmp = verCmp_(t.ver, CORE_VER);
    if (cmp === 0 && !opts.force) return { ok: true, msg: '이미 최신 버전입니다 (' + CORE_VER + ').', current: CORE_VER };
    if (cmp < 0 && t.why !== 'pin' && !opts.to) return { ok: true, msg: '지금 버전이 더 새롭습니다.', current: CORE_VER };
    if ((m.blocked || []).indexOf(t.ver) >= 0) return { ok: false, error: t.ver + ' 버전은 판매자가 배포를 멈췄습니다.' };
    if (verParts_(t.ver)[0] > verParts_(CORE_VER)[0] && !opts.optIn && PROPS.getProperty('UPDATE_MAJOR_OK') !== '1')
      return { ok: false, code: 'MAJOR', error: t.ver + ' 은 큰 업그레이드라 편집기에서 「올리기」를 눌러야 적용됩니다.' };
    var info = m.bundles[t.ver];
    if (!info || !info.url || !info.sha256) return { ok: false, error: t.ver + ' 버전 묶음 정보가 없습니다.' };

    /* ① 묶음 받기 + 지문 확인 */
    var res = updateGet_(info.url);
    if (res.getResponseCode() !== 200) throw new Error('엔진 묶음을 받지 못했습니다 (HTTP ' + res.getResponseCode() + ')');
    var text = res.getContentText('UTF-8');
    if (hex_(Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, text, Utilities.Charset.UTF_8)) !== String(info.sha256).toLowerCase())
      throw new Error('엔진 묶음 지문이 맞지 않습니다 (받는 도중 바뀌었거나 판매자 파일이 다름). 아무것도 바꾸지 않았습니다.');
    var bundle = safeJson_(text);
    if (!bundle || bundle.app !== 'sitelumi' || bundle.version !== t.ver || !Array.isArray(bundle.files) || !bundle.files.length) throw new Error('엔진 묶음 형식이 올바르지 않습니다.');

    /* ② 파일 바꾸기 (my_ 파일 보존, 시간대는 이 프로젝트 것 유지) */
    var sid = ScriptApp.getScriptId(), cur = scriptApi_('get', '/projects/' + sid + '/content');
    var keep = (cur.files || []).filter(function (f) { return UPDATE_KEEP_RE.test(f.name); });
    var curManifest = (cur.files || []).filter(function (f) { return f.name === 'appsscript'; })[0];
    var files = bundle.files.filter(function (f) { return !UPDATE_KEEP_RE.test(f.name); }).map(function (f) {
      var src = f.source;
      if (f.name === 'appsscript' && curManifest) {
        var a = safeJson_(src) || {}, b = safeJson_(curManifest.source) || {};
        if (b.timeZone) a.timeZone = b.timeZone;
        src = JSON.stringify(a, null, 2);
      }
      return { name: f.name, type: f.type, source: src };
    }).concat(keep);
    if (!files.some(function (f) { return f.name === 'appsscript'; })) throw new Error('묶음에 appsscript.json 이 없습니다.');

    var prevDeployVer = deployedVersion_();
    scriptApi_('put', '/projects/' + sid + '/content', { files: files });

    /* ③ 새 버전 → 웹앱 배포 옮기기 */
    var v = scriptApi_('post', '/projects/' + sid + '/versions', { description: 'sitelumi ' + t.ver + ' (자동 업그레이드, ' + CORE_VER + '에서)' });
    var dep = moveDeployment_(v.versionNumber, 'sitelumi ' + t.ver);
    if (prevDeployVer) PROPS.setProperty('UPDATE_PREV_VERSION', String(prevDeployVer));
    PROPS.setProperty('UPDATE_LAST', JSON.stringify({ from: CORE_VER, to: t.ver, at: new Date().toISOString(), version: v.versionNumber, why: t.why }));
    PROPS.deleteProperty('UPDATE_ERR');
    CacheService.getScriptCache().remove('UPD_MANIFEST');
    updateReport_(t.ver, 'updated');
    return { ok: true, msg: t.ver + ' 버전으로 바꿨습니다. 편집기를 새로 고쳐 주세요.', from: CORE_VER, to: t.ver, deployment: dep };
  } catch (e) {
    PROPS.setProperty('UPDATE_ERR', new Date().toISOString().slice(0, 16) + ' ' + String(e.message || e).slice(0, 300));
    return { ok: false, error: String(e.message || e) };
  } finally { lock.releaseLock(); }
}

/** 바로 전 버전으로 되돌리기: 그 버전의 파일을 다시 깔고 배포도 그 버전으로 */
function updateRollback_() {
  var prev = Number(PROPS.getProperty('UPDATE_PREV_VERSION') || 0);
  if (!prev) return { ok: false, error: '되돌릴 이전 버전 기록이 없습니다.' };
  var lock = LockService.getScriptLock();
  if (!lock.tryLock(30000)) return { ok: false, error: '다른 작업이 진행 중입니다.' };
  try {
    var sid = ScriptApp.getScriptId();
    var old = scriptApi_('get', '/projects/' + sid + '/content?versionNumber=' + prev);
    scriptApi_('put', '/projects/' + sid + '/content', { files: old.files });          // 자동 기록(트리거)도 옛 코드로
    moveDeployment_(prev, 'sitelumi 되돌림 (버전 ' + prev + ')');
    PROPS.deleteProperty('UPDATE_PREV_VERSION');
    PROPS.setProperty('UPDATE_PIN_LOCAL', CORE_VER);                                  // 되돌린 뒤 자동 업그레이드가 곧바로 다시 올리지 않게
    PROPS.setProperty('UPDATE_LAST', JSON.stringify({ from: CORE_VER, to: 'v' + prev, at: new Date().toISOString(), why: 'rollback' }));
    updateReport_('v' + prev, 'rollback');
    return { ok: true, msg: '이전 버전으로 되돌렸습니다. 편집기를 새로 고쳐 주세요. 자동 업그레이드는 다음 새 버전이 나올 때까지 쉽니다.' };
  } catch (e) { return { ok: false, error: String(e.message || e) }; }
  finally { lock.releaseLock(); }
}

/** 매일 자동 확인 (트리거) */
function slAutoUpdate() {
  try {
    var info = updateInfo_(true);
    if (info.checkErr || !info.newer || info.blocked) return;
    var pinLocal = PROPS.getProperty('UPDATE_PIN_LOCAL');
    if (pinLocal && verCmp_(info.target, pinLocal) <= 0) return;                     // 되돌린 버전보다 새 것이 나와야 다시 자동
    if (info.major && !info.majorOk) return;                                         // 큰 업그레이드는 버튼으로만
    var r = updateApply_({});
    if (r.ok) PROPS.deleteProperty('UPDATE_PIN_LOCAL');
  } catch (e) { PROPS.setProperty('UPDATE_ERR', new Date().toISOString().slice(0, 16) + ' ' + String(e.message || e).slice(0, 300)); }
}
function installUpdateTrigger_() {
  var has = ScriptApp.getProjectTriggers().some(function (t) { return t.getHandlerFunction() === 'slAutoUpdate'; });
  if (!has) ScriptApp.newTrigger('slAutoUpdate').timeBased().atHour(UPDATE_HOUR).nearMinute(Math.floor(Math.random() * 60)).everyDays(1).inTimezone('Asia/Seoul').create();
  return !has;
}

/* ───── Apps Script API ───── */
function scriptApi_(method, path, body) {
  var opt = { method: method, headers: { Authorization: 'Bearer ' + ScriptApp.getOAuthToken() }, muteHttpExceptions: true };
  if (body) { opt.contentType = 'application/json'; opt.payload = JSON.stringify(body); }
  var res = UrlFetchApp.fetch('https://script.googleapis.com/v1' + path, opt), code = res.getResponseCode(), txt = res.getContentText();
  if (code >= 200 && code < 300) return safeJson_(txt) || {};
  if (/User has not enabled the Apps Script API/i.test(txt)) throw new Error('script.google.com/home/usersettings 에서 「Google Apps Script API」를 켜 주세요.');
  if (/Apps Script API has not been used|SERVICE_DISABLED|accessNotConfigured/i.test(txt)) throw new Error('연결된 GCP 프로젝트에서 「Apps Script API」를 사용 설정해 주세요.');
  if (code === 403 && /insufficient|scope/i.test(txt)) throw new Error('업그레이드 권한이 아직 없습니다. 앱스 스크립트에서 「설치하기」를 한 번 실행해 권한을 허용해 주세요.');
  throw new Error('APPS_SCRIPT_API_' + code + ': ' + txt.slice(0, 200));
}
/** 지금 웹앱 배포가 가리키는 버전 번호 */
function deployedVersion_() {
  var d = webDeployment_();
  return d && d.deploymentConfig ? Number(d.deploymentConfig.versionNumber || 0) : 0;
}
/** 편집기 주소(WEBAPP_URL)와 같은 웹앱 배포 찾기 (없으면 첫 웹앱 배포) */
function webDeployment_() {
  var sid = ScriptApp.getScriptId(), saved = PROPS.getProperty('DEPLOY_ID');
  var list = (scriptApi_('get', '/projects/' + sid + '/deployments?pageSize=50').deployments || []).filter(function (d) {
    return (d.entryPoints || []).some(function (e) { return e.entryPointType === 'WEB_APP'; }) && d.deploymentConfig && d.deploymentConfig.versionNumber;
  });
  var url = webAppUrl_(), pick = null;
  list.forEach(function (d) {
    if (saved && d.deploymentId === saved) pick = d;
    (d.entryPoints || []).forEach(function (e) { if (!pick && url && e.webApp && e.webApp.url === url) pick = d; });
  });
  pick = pick || list[0] || null;
  if (pick) PROPS.setProperty('DEPLOY_ID', pick.deploymentId);
  return pick;
}
function moveDeployment_(versionNumber, desc) {
  var d = webDeployment_();
  if (!d) throw new Error('웹앱 배포를 찾지 못했습니다. [배포 › 새 배포 › 웹 앱]으로 한 번 배포해 주세요.');
  scriptApi_('put', '/projects/' + ScriptApp.getScriptId() + '/deployments/' + d.deploymentId, {
    deploymentConfig: { scriptId: ScriptApp.getScriptId(), versionNumber: versionNumber, manifestFileName: 'appsscript', description: desc }
  });
  return d.deploymentId;
}

/** 판매자 사이트 목록에 알림 (선택: manifest.report 주소가 있을 때만, 실패해도 무시) */
function updateReport_(ver, event) {
  try {
    var m = updateManifest_(false);
    if (!m.report) return;
    UrlFetchApp.fetch(m.report, { method: 'post', contentType: 'application/json', muteHttpExceptions: true,
      payload: JSON.stringify({ a: 'siteReport', blogId: PROPS.getProperty('BLOG_ID') || '', blog: blogUrl_(), name: PROPS.getProperty('BLOG_ID') ? blogName_() : '', webapp: PROPS.getProperty('WEBAPP_URL') || '', ver: ver, event: event, at: new Date().toISOString() }) });
  } catch (e) {}
}
